=== GET /v1/recommendations/search ===
summary: Get ranked search catalog
description: Returns a ranked product catalog for the resolved `brand` and `locale`, with optional filters applied by the recommender upstream.
 param: None None required=None None
 param: None None required=None None
 param: category query required=None {'type': 'string'}
 param: destination query required=None {'type': 'string'}
 param: country query required=None {'type': 'string'}
 param: date_from query required=None {'type': 'string', 'format': 'date'}
 param: date_to query required=None {'type': 'string', 'format': 'date'}
 param: keyword query required=None {'type': 'string'}
 param: price_min query required=None {'type': 'number'}
 param: price_max query required=None {'type': 'number'}
 param: top_n query required=None {'type': 'integer', 'minimum': 1, 'maximum': 200, 'default': 10}
 param: slim query required=None {'type': 'boolean', 'default': False}

=== GET /v1/products ===
summary: List products
description: 
 param: limit query required=None {'type': 'integer', 'minimum': 1, 'maximum': 100, 'default': 25}
 param: cursor query required=None {'type': 'string'}
 param: channelIds query required=None {'type': 'string'}
 param: brand query required=None {'type': 'string'}
 param: locale query required=None {'type': 'string'}

=== POST /v1/itineraries ===
summary: Create itinerary (internal)
description: Create a new itinerary (shopping cart) on the brand site for the resolved `?brand=`. Returns the `itineraryId` to use on every subsequent checkout call. Internal clients only — requires `profile=internal` and `allowedEntities` includes `itineraries`.
 param: None None required=None None
 param: None None required=None None
 requestBody: {
 "required": true,
 "content": {
  "application/json": {
   "schema": {
    "type": "object",
    "required": [
     "productId",
     "startDate",
     "adults",
     "rooms"
    ],
    "properties": {
     "productId": {
      "oneOf": [
       {
        "type": "integer"
       },
       {
        "type": "string"
       }
      ],
      "description": "Product identifier for the brand site. Accept either the numeric CMS id returned by `GET /v1/products` (e.g. `181`) or the alphanumeric trip / provider code (e.g. `t0054825`, returned by `GET /v1/products/tripcode/...`)."
     },
     "startDate": {
      "type": "string",
      "format": "date",
      "description": "Trip start date (`YYYY-MM-DD`)."
     },
     "adults": {
      "type": "integer",
      "minimum": 1,
      "description": "Number of adult passengers."
     },
     "rooms": {
      "type": "integer",
      "minimum": 1,
      "description": "Number of rooms requested."
     },
     "affiliateId": {
      "type": "string",
      "nullable": true,
      "description": "Optional affiliate identifier for attribution."
     },
     "currency": {
      "type": "string",
      "enum": [
       "EUR",
       "USD",
       "GBP"
      ],
      "default": "EUR",
      "description": "Pricing currency for the itinerary."
     },
     "withoutNavigations": {
      "type": "boolean",
      "default": false,
      "description": "If true, the brand site hides header/footer in the embedded checkout layout."
     }
    }

=== POST /v1/bookings ===
summary: Confirm booking (internal)
description: Upsert the reservation for the itinerary. Call this AFTER the Stripe payment has been confirmed on the frontend. The response contains the human-readable reservation code shown on the thank-you page.
 param: None None required=None None
 param: None None required=None None
 requestBody: {
 "required": true,
 "content": {
  "application/json": {
   "schema": {
    "type": "object",
    "required": [
     "itineraryId"
    ],
    "properties": {
     "itineraryId": {
      "type": "string",
      "description": "Itinerary to confirm."
     }
    }
   }
  }
 }
}

=== GET /v1/itineraries/{itineraryId}/payment ===
summary: Refresh Stripe payment intent (internal)
description: Refresh the Stripe payment intent for the itinerary and return its `client_secret`. Pass the secret to Stripe.js on the frontend to complete payment.
 param: None None required=None None
 param: None None required=None None
 param: None None required=None None

