private async runCollecting(state: ConversationState): Promise<string> {
  const missing = this.firstMissingTripSlot(state.slots);
  // A vague date answer ("un weekend a novembre") still counts as an
  // answer: don't keep re-asking for precision the traveller may not
  // have. classify()'s date_unspecified compromise turns straight into
  // a concrete proposal ("non hai una data precisa? ti propongo il primo
  // slot libero, il 9 ottobre") — that message does double duty as both
  // acknowledgment and offer, which is a better turn than "let me ask
  // again" followed by a search on some later turn. Read from
  // state.slots.dateFromVague (persisted, not a per-turn local) so this
  // still fires even if the vague phrase was said on an earlier turn,
  // while some other slot was the one actually missing at the time.
  if (missing === "dateFrom" && state.slots.dateFromVague) {
    return this.searchAndPropose(state);
  }
  // City and budget both get a patience budget before the dialogue
  // stops re-asking and lets searchCandidates/classify's
  // location_unspecified / budget_unspecified compromise take over —
  // propose something concrete, disclosed, rather than interrogate
  // indefinitely (live regression: a real user got stuck 10+ turns
  // because "city" kept capturing something unsearchable). Budget gets
  // only one ask before deciding (BUDGET_LOOP_BREAKER = 1): once every
  // *other* required slot is known and budget still isn't, after that
  // single ask there's nothing left to wait for. Adults is deliberately
  // exempt from both — never bypassed, only ever asked, per explicit
  // policy (see ARCHITECTURE.md, "mai un default onesto per queste due").
  if (missing === "city" && state.cityAskAttempts >= CITY_LOOP_BREAKER) {
    return this.searchAndPropose(state);
  }
  if (missing === "budget" && state.budgetAskAttempts >= BUDGET_LOOP_BREAKER) {
    return this.searchAndPropose(state);
  }
  if (missing === "city") {
    state.cityAskAttempts += 1;
    return say(this.env, { kind: "ask_slot", missing });
  }
  if (missing === "budget") {
    state.budgetAskAttempts += 1;
    return say(this.env, { kind: "ask_slot", missing });
  }
  if (missing) {
    return say(this.env, { kind: "ask_slot", missing });
  }
  return this.searchAndPropose(state);
}

private async searchAndPropose(state: ConversationState): Promise<string> {
  const { candidates, locationMatched } = await searchCandidates(this.hofj, state.slots);
  const ctx = classify(state.slots, candidates, state.rejectedProductIds, locationMatched);
  if (!ctx) {
    state.stage = "collecting";
    return say(this.env, { kind: "no_match" });
  }
  state.cityAskAttempts = 0;
  state.budgetAskAttempts = 0;

