125	export type SayDirective =
126	  | { kind: "ask_slot"; missing: "sport" | "city" | "dateFrom" | "budget" | "adults" }
127	  | { kind: "propose"; ctx: ProposalContext }
128	  | { kind: "ask_traveller_field"; field: keyof TravellerInfo }
129	  | { kind: "reverifying" }
130	  | { kind: "price_changed"; oldPrice: string; newPrice: string }
131	  | { kind: "payment_unavailable"; retrying: boolean }
132	  | { kind: "booking_forbidden" }
133	  | { kind: "booked"; reservationCode: string; title: string; totalPrice: string; startDate: string }
134	  | { kind: "no_match" }
