137	const SAY_SYSTEM = `Sei la voce di un agente di prenotazione viaggi sportivi (padel/tennis + hotel), pensato per essere ascoltato più che letto: l'interazione è vocale, il viaggiatore potrebbe non guardare uno schermo. Parla in modo naturale, caldo, diretto, come faresti al telefono.
138	Regole ferree:
139	- UN SOLO messaggio breve (1-3 frasi), MAI un elenco, MAI più di una proposta/opzione alla volta.
140	- Usa SOLO i fatti forniti nell'istruzione — non inventare prezzi, date o dettagli.
141	- Se c'è un compromesso (prezzo o data diversi da quanto chiesto), dillo esplicitamente e chiedi conferma, sul modello: "non riesco a X, riesco a Y, procedo?".
142	- Rispondi in italiano, tono colloquiale ma professionale.
143	- Se la proposta è "exact" (nessun compromesso), presenta la proposta con entusiasmo misurato e chiedi conferma.`;
144	
145	function directiveToInstruction(d: SayDirective): string {
146	  switch (d.kind) {
147	    case "ask_slot": {
148	      const labels: Record<typeof d.missing, string> = {
149	        sport: "che sport vuole praticare (tennis o padel)",
150	        city: "in che città o zona vuole andare",
151	        dateFrom: "quando vuole partire",
152	        budget: "qual è il budget indicativo",
153	        adults: "in quante persone viaggia",
154	      };
155	      return `Chiedi al viaggiatore, in una frase breve, ${labels[d.missing]}. Non chiedere altro insieme.`;
156	    }
157	    case "propose": {
158	      const { candidate, category, compromise } = d.ctx;
159	      const base = `Proponi ESATTAMENTE questo pacchetto, uno solo: "${candidate.title}" a ${candidate.venue}, ${candidate.city}, prezzo ${candidate.price}${candidate.currency === "EUR" ? "€" : " " + candidate.currency}, ${candidate.durationDays} giorni, disponibile tra ${candidate.minDate} e ${candidate.maxDate}.`;
160	      if (category === "exact") return `${base} Corrisponde esattamente a quanto chiesto. Chiedi conferma per procedere.`;
161	      const c = compromise!;
162	      if (c.kind === "date_unspecified") {
163	        return `${base} Il viaggiatore non ha dato una data precisa (ha detto qualcosa di vago tipo un periodo o un mese). Diglielo con naturalezza — non è un problema, hai semplicemente scelto per lui la prima disponibilità utile, il ${c.offered} — e chiedi conferma o se preferisce specificare un'altra data.`;
164	      }
165	      if (c.kind === "location_unspecified") {
166	        const askedFor = c.requested ? `aveva detto "${c.requested}" (non abbastanza preciso per trovare qualcosa lì)` : "non ha specificato una città o zona precisa";
167	        return `${base} Il viaggiatore ${askedFor}. Hai scelto tu ${candidate.city} come destinazione — diglielo con naturalezza, non è un problema, e chiedi conferma o se preferisce indicare un'altra città.`;
168	      }
169	      if (c.kind === "budget_unspecified") {
170	        return `${base} Il viaggiatore non ti ha mai detto un budget. Diglielo con naturalezza — non è un problema, hai scelto tu il pacchetto più economico tra quelli pertinenti, a ${c.offered} — e chiedi conferma o se preferisce dirti un budget preciso.`;
171	      }
172	      return `${base} ATTENZIONE: c'è uno scostamento su ${c.kind === "price" ? "prezzo" : "data"} — il viaggiatore voleva ${c.requested}, tu puoi offrire ${c.offered}. Dillo chiaramente nello stile "non riesco a ${c.requested}, riesco a ${c.offered}, procedo?" e chiedi conferma esplicita.`;
173	    }
174	    case "ask_traveller_field": {
175	      const labels: Record<string, string> = {
176	        firstName: "il nome",
177	        lastName: "il cognome",
178	        email: "l'indirizzo email",
179	        phone: "il numero di telefono",
180	        city: "la città di residenza",
181	        postalCode: "il CAP",
182	        countryCode: "il paese",
183	      };
184	      return `Spiega in una frase che per procedere alla prenotazione reale ti servono i dati del viaggiatore, e chiedi ${labels[d.field] ?? d.field}.`;
185	    }
186	    case "reverifying":
187	      return `Di' in una frase breve che stai ricontrollando prezzo e disponibilità reali prima di chiudere, perché l'inventario è condiviso e potrebbe essere cambiato nel frattempo. Tono rassicurante.`;
188	    case "price_changed":
189	      return `Il prezzo è cambiato nel frattempo: era ${d.oldPrice}, ora è ${d.newPrice}. Comunicalo con onestà e chiedi se vuole procedere comunque al nuovo prezzo.`;
190	    case "payment_unavailable":
191	      return d.retrying
192	        ? `Il sistema di pagamento non risponde in questo momento. Di' che ci stai riprovando subito, tono rassicurante, una frase.`
193	        : `Il sistema di pagamento del fornitore non è disponibile in questo momento (problema tecnico loro, non del viaggiatore). Scusati brevemente e chiedi se preferisce che ci riprovi tra poco o che lasci i suoi dati per essere ricontattato appena torna disponibile.`;
