1	import type { Env, ProposalContext, Slots, TravellerInfo } from "../types";
2	
3	const WORKERS_AI_MODEL = "@cf/meta/llama-3.3-70b-instruct-fp8-fast";
4	const ANTHROPIC_MODEL = "claude-haiku-4-5-20251001";
5	
6	function extractJson<T>(raw: string): T | null {
7	  const start = raw.indexOf("{");
8	  const end = raw.lastIndexOf("}");
9	  if (start === -1 || end === -1 || end < start) return null;
10	  try {
11	    return JSON.parse(raw.slice(start, end + 1)) as T;
12	  } catch {
13	    return null;
14	  }
15	}
16	
17	export class AiUnavailableError extends Error {}
18	
19	// Workers AI occasionally throws a transient "internal error" (observed
20	// live, not model-specific — happens across models). Not worth failing an
21	// entire conversation over, so retry a couple of times before falling back
22	// / giving up — same spirit as the HOFJ client's retry-once-on-transient.
23	//
24	// Error 4006 is different: it means the daily free neuron allocation is
25	// exhausted (hit for real on 2026-09-14 after the k6 load test — see
26	// ARCHITECTURE.md). That's not transient within the day, so retrying is
27	// pure wasted latency — fail straight to the Anthropic fallback instead.
28	function isQuotaExhausted(err: unknown): boolean {
29	  return err instanceof Error && err.message.includes("4006");
30	}
31	
32	async function runWorkersAi(env: Env, system: string, user: string): Promise<string> {
33	  let lastErr: unknown;
34	  for (let attempt = 0; attempt < 3; attempt++) {
35	    try {
36	      const res = await env.AI.run(WORKERS_AI_MODEL, {
37	        messages: [
38	          { role: "system", content: system },
39	          { role: "user", content: user },
40	        ],
41	        temperature: 0.3,
42	      });
43	      const shaped = res as { response?: unknown; choices?: { message?: { content?: string } }[] };
44	      const text =
45	        typeof shaped.response === "string" ? shaped.response : shaped.choices?.[0]?.message?.content;
46	      if (typeof text === "string" && text.trim().length > 0) return text;
47	      throw new Error("empty Workers AI response: " + JSON.stringify(res).slice(0, 300));
48	    } catch (err) {
49	      lastErr = err;
50	      console.error(`Workers AI attempt ${attempt + 1}/3 failed:`, err instanceof Error ? err.message : err);
51	      if (isQuotaExhausted(err)) break;
52	      if (attempt < 2) await new Promise((r) => setTimeout(r, 250 * (attempt + 1)));
53	    }
54	  }
55	  throw lastErr;
56	}
57	
58	async function chat(env: Env, system: string, user: string): Promise<string> {
59	  try {
60	    return await runWorkersAi(env, system, user);
61	  } catch (err) {
62	    if (!env.ANTHROPIC_API_KEY) throw new AiUnavailableError(err instanceof Error ? err.message : String(err));
63	    const res = await fetch("https://api.anthropic.com/v1/messages", {
64	      method: "POST",
65	      headers: {
66	        "x-api-key": env.ANTHROPIC_API_KEY,
67	        "anthropic-version": "2023-06-01",
68	        "content-type": "application/json",
69	      },
70	      body: JSON.stringify({
71	        model: ANTHROPIC_MODEL,
72	        max_tokens: 512,
73	        system,
74	        messages: [{ role: "user", content: user }],
75	      }),
76	    });
77	    if (!res.ok) throw new AiUnavailableError(`Anthropic fallback failed: ${res.status}`);
78	    const body = await res.json<{ content: { text: string }[] }>();
79	    return body.content.map((b) => b.text).join("");
80	  }
81	}
