83	interface RawInterpretation {
84	  slotUpdates: Partial<Omit<Slots, "dateFrom" | "dateTo" | "dateFromVague">> & {
85	    dateFromText?: string | null;
86	    dateToText?: string | null;
87	  };
88	  travellerUpdates: Partial<TravellerInfo>;
89	  decision: "yes" | "no" | "unclear";
90	}
