113	  currentlyAsking: string | null = null,
114	): Promise<RawInterpretation> {
115	  // "city" exists on both slots (trip destination) and traveller (billing
116	  // address) — without knowing which question was just asked, a bare
117	  // answer like "Milano" is genuinely ambiguous. Verified live: this
118	  // caused the traveller's real destination to get silently overwritten
119	  // by their billing city on one turn, and on a later turn (after slots
120	  // become locked once the trip is confirmed — see conversation.ts) the
121	  // answer was dropped entirely because the model put it in the now-
122	  // discarded slotUpdates.city instead of travellerUpdates.city. Passing
123	  // what's actually being asked resolves the ambiguity at the source
124	  // instead of only guarding against its worst consequence.
125	  const askContext = currentlyAsking ? `\nStai chiedendo in questo momento: ${currentlyAsking}` : "";
126	  const user = `Stato attuale: ${JSON.stringify({ slots: currentSlots, traveller: currentTraveller })}${askContext}\nMessaggio del viaggiatore: "${latestUserText}"`;
127	  const raw = await chat(env, INTERPRET_SYSTEM, user);
128	  const parsed = extractJson<RawInterpretation>(raw);
129	  return (
130	    parsed ?? {
131	      slotUpdates: {},
132	      travellerUpdates: {},
133	      decision: "unclear",
134	    }
135	  );
136	}
