138	export type SayDirective =
139	  | { kind: "ask_slot"; missing: "sport" | "city" | "dateFrom" | "budget" | "adults" }
140	  | { kind: "propose"; ctx: ProposalContext; precededBy?: "rejected" | "unavailable" }
141	  | { kind: "ask_traveller_field"; field: keyof TravellerInfo; isFirstAsk: boolean }
142	  | { kind: "reverifying" }
143	  | { kind: "price_changed"; oldPrice: string; newPrice: string }
144	  | { kind: "payment_unavailable"; retrying: boolean }
145	  | { kind: "booking_forbidden" }
146	  | { kind: "booked"; reservationCode: string; title: string; totalPrice: string; startDate: string }
147	  | { kind: "no_match" };
148	
149	const SAY_SYSTEM = `Sei la voce di un agente di prenotazione viaggi sportivi (padel/tennis + hotel), pensato per essere ascoltato più che letto: l'interazione è vocale, il viaggiatore potrebbe non guardare uno schermo. Parla in modo naturale, caldo, diretto, come faresti al telefono.
150	Regole ferree:
151	- UN SOLO messaggio breve (1-3 frasi), MAI un elenco, MAI più di una proposta/opzione alla volta.
152	- Usa SOLO i fatti forniti nell'istruzione — non inventare prezzi, date o dettagli.
153	- Se c'è un compromesso (prezzo o data diversi da quanto chiesto), dillo esplicitamente e chiedi conferma, sul modello: "non riesco a X, riesco a Y, procedo?".
