1	export interface Env {
2	  AI: Ai;
3	  ASSETS: Fetcher;
4	  CONVERSATION: DurableObjectNamespace<import("./conversation").ConversationDO>;
5	  HOFJ_BASE_URL: string;
6	  HOFJ_BRAND: string;
7	  HOFJ_LOCALE: string;
8	  HOFJ_API_KEY: string;
9	  ANTHROPIC_API_KEY?: string;
10	  STRIPE_PUBLISHABLE_KEY?: string;
11	}
12	
13	/** What we've gathered from the traveller so far. Only sport/city are hard
14	 * requirements to run a search; the rest sharpen the match. */
15	export interface Slots {
16	  sport: "tennis" | "padel" | null;
17	  city: string | null;
18	  dateFrom: string | null; // YYYY-MM-DD, requested start
19	  dateTo: string | null; // YYYY-MM-DD, requested end (optional, inferred from product duration if absent)
20	  /** A date phrase heard but not yet resolved to a specific day (e.g. "nei
21	   * prossimi tre mesi") — persisted across turns so the signal survives
22	   * even when dateFrom isn't the slot being asked about *this* turn (e.g.
23	   * the traveller volunteers a vague date while city is still missing).
24	   * Checked whenever dateFrom next becomes the missing slot, not only in
25	   * the turn it was said. Cleared once a real dateFrom is resolved. */
26	  dateFromVague: string | null;
27	  budget: number | null; // EUR, total for the trip
28	  /** A qualitative budget answer ("economico"/"il top") that doesn't map
29	   * to a number — a real answer, not a missing one, so it must not be
30	   * treated as budget_unspecified. "low" biases selection toward the
31	   * cheapest relevant candidate; "high" means no ceiling, keep the
32	   * default (most relevant) selection. Mutually exclusive with `budget`
