30	/** Deterministic Italian/ISO date resolver. Calendar arithmetic is exactly
31	 * the kind of thing an LLM gets subtly wrong (verified live: Workers AI
32	 * Llama-3.3-70B returned "1970"/"1971" as the year despite an explicit
33	 * "today is 2026-09-14, never use 1970" instruction) — so the model is only
34	 * asked to lift the raw date phrase out of the sentence; resolving it to a
35	 * real calendar date happens here, in code, where it's testable. */
36	export function resolveDate(raw: string | null, now: Date = new Date()): string | null {
37	  if (!raw) return null;
38	  const text = raw.trim().toLowerCase();
39	
40	  const isoMatch = text.match(/(\d{4})-(\d{2})-(\d{2})/);
41	  if (isoMatch) return `${isoMatch[1]}-${isoMatch[2]}-${isoMatch[3]}`;
42	
43	  // "9/10/2026", "9-10-2026", "09.10.2026" — Italian convention is
44	  // day/month/year, not the US month/day/year (regression: "9/10/2026"
45	  // typed literally by a traveller was silently dropped, see
46	  // ARCHITECTURE.md for the live repro).
47	  const slashMatch = text.match(/\b(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{4})\b/);
48	  if (slashMatch) {
49	    const day = Number(slashMatch[1]);
50	    const month = Number(slashMatch[2]);
51	    const year = Number(slashMatch[3]);
52	    if (month >= 1 && month <= 12 && day >= 1 && day <= 31) {
53	      return toIso(new Date(Date.UTC(year, month - 1, day)));
54	    }
55	  }
56	
57	  if (/\boggi\b/.test(text)) return toIso(now);
58	  if (/\bdomani\b/.test(text)) return toIso(addDays(now, 1));
59	  if (/\bdopodomani\b/.test(text)) return toIso(addDays(now, 2));
60	
61	  const inDays = text.match(/tra\s+(\d+)\s+giorni/);
62	  if (inDays) return toIso(addDays(now, Number(inDays[1])));
63	  const inWeeks = text.match(/tra\s+(\d+)\s+settiman/);
64	  if (inWeeks) return toIso(addDays(now, Number(inWeeks[1]) * 7));
65	
