46	function mergeDefined<T extends object>(target: T, updates: Partial<T>): T {
47	  const out = { ...target };
48	  for (const [k, v] of Object.entries(updates)) {
49	    if (v !== null && v !== undefined) (out as Record<string, unknown>)[k] = v;
50	  }
51	  return out;
52	}
53	
54	export interface HandleMessageResult {
55	  reply: string;
56	  state: ConversationState;
57	}
58	
59	export class ConversationDO extends DurableObject<Env> {
60	  private hofj: HofjClient;
61	
62	  constructor(ctx: DurableObjectState, env: Env) {
63	    super(ctx, env);
64	    this.hofj = new HofjClient(env);
65	  }
66	
67	  private async loadState(): Promise<ConversationState> {
68	    const stored = await this.ctx.storage.get<ConversationState>("state");
69	    return stored ?? initialState();
70	  }
71	
72	  private async saveState(state: ConversationState): Promise<void> {
73	    await this.ctx.storage.put("state", state);
74	  }
75	
76	  async getState(): Promise<ConversationState> {
77	    return this.loadState();
78	  }
79	
80	  /** Single entry point for every traveller turn. Runs entirely inside this
81	   * DO instance, which naturally serializes concurrent messages for the
82	   * same conversation — that's also what stops a double /v1/bookings call
83	   * if the traveller (or a flaky client) sends "sì" twice in a row. */
84	  async handleMessage(text: string): Promise<HandleMessageResult> {
85	    let state = await this.loadState();
86	    state.messages.push({ role: "traveller", text, at: Date.now() });
87	
88	    if (state.stage === "booked") {
89	      const reply = `La tua prenotazione è già confermata, codice ${state.reservationCode}. Per un nuovo viaggio apri una nuova conversazione.`;
90	      state.messages.push({ role: "agent", text: reply, at: Date.now() });
91	      await this.saveState(state);
92	      return { reply, state };
93	    }
94	
95	    // The HOFJ inventory/backend is shared and can change mid-session (the
96	    // brief flags this explicitly) — a payment failure specifically is
97	    // exactly the transient-looking case worth letting the traveller
98	    // retry, without starting a whole new conversation/cart. A bookings
99	    // permission failure (403) is not: retrying won't fix a missing
100	    // entitlement, so that one stays terminal.
101	    if (state.stage === "failed") {
102	      const retryable = state.failureReason?.startsWith("payment:") && state.itineraryId;
103	      const wantsRetry = /riprova|di nuovo|ritenta|prova ancora|retry/i.test(text);
104	      if (retryable && wantsRetry) {
105	        const reply = await this.attemptPayment(state);
106	        state.messages.push({ role: "agent", text: reply, at: Date.now() });
107	        await this.saveState(state);
108	        return { reply, state };
109	      }
110	      const reply = retryable
111	        ? `Il pagamento non è ancora disponibile. Dimmi "riprova" quando vuoi che ci riprovi, oppure apri una nuova conversazione.`
112	        : `Questa conversazione si è fermata per un problema tecnico (${state.failureReason ?? "errore"}). Apri una nuova conversazione per riprovare.`;
113	      state.messages.push({ role: "agent", text: reply, at: Date.now() });
114	      await this.saveState(state);
115	      return { reply, state };
116	    }
117	
118	    let reply: string;
119	    try {
120	      const interpretation = await interpret(this.env, state.slots, state.traveller, text, this.describeCurrentlyAsking(state));
121	      const { dateFromText, dateToText, ...slotUpdates } = interpretation.slotUpdates as Record<string, unknown>;
122	
123	      // Trip slots (sport/city/dates/budget/...) and traveller fields both
124	      // have a "city", and interpret() isn't told which stage we're in —
125	      // it has to guess from context alone. Verified live: once the trip
126	      // was already confirmed and the dialogue was asking for the
127	      // traveller's own city (billing address), a bare answer like
128	      // "Milano" got written into BOTH state.traveller.city AND
129	      // state.slots.city, silently corrupting the already-confirmed
130	      // destination (a real proposal for Lanzarote ended up with
131	      // slots.city == "Lecco"). Prompt instructions alone aren't a
132	      // reliable enough guard for something this consequential — the trip
133	      // is only ever open for renegotiation during "collecting"/
134	      // "proposing"; past that point it's locked, so slotUpdates (except
135	      // dateFromVague bookkeeping) simply isn't applied at all, regardless
136	      // of what the model returned.
137	      const tripStillNegotiable = state.stage === "collecting" || state.stage === "proposing";
138	      if (tripStillNegotiable) {
139	        const resolvedDates: Partial<Slots> = {};
140	        if (typeof dateFromText === "string") resolvedDates.dateFrom = resolveDate(dateFromText);
141	        if (typeof dateToText === "string") resolvedDates.dateTo = resolveDate(dateToText);
142	        state.slots = mergeDefined(state.slots, { ...slotUpdates, ...resolvedDates } as Partial<Slots>);
143	
144	        // The traveller said *something* about a date, but it wasn't
145	        // specific enough to resolve to one calendar day (e.g. "un weekend
146	        // di novembre") — worth telling them that, instead of silently
147	        // re-asking the same generic question, which reads as "didn't hear
148	        // you" when it actually did (regression: live user hit exactly this
149	        // with vague month-only answers, repeated 3+ times). Persisted on
150	        // the slots themselves (not a local variable) so it survives to a
151	        // *later* turn when dateFrom next becomes the missing slot — a
152	        // second regression found reading this code: the traveller can
153	        // volunteer a vague date on a turn where city, not date, is what's
154	        // being asked about, and that signal was being silently dropped.
155	        if (typeof dateFromText === "string") {
156	          state.slots.dateFromVague = resolvedDates.dateFrom ? null : dateFromText;
157	        }
158	      }
159	      state.traveller = mergeDefined(state.traveller, interpretation.travellerUpdates);
160	
161	      switch (state.stage) {
162	        case "collecting":
163	          reply = await this.runCollecting(state);
164	          break;
165	        case "proposing":
166	          reply = await this.runProposing(state, interpretation.decision);
167	          break;
168	        case "collecting_traveller":
169	          reply = await this.runCollectingTraveller(state);
170	          break;
171	        default:
172	          reply = await say(this.env, { kind: "no_match" });
173	      }
174	    } catch (err) {
175	      reply = await this.handleUnexpectedError(state, err);
176	    }
177	
178	    state.messages.push({ role: "agent", text: reply, at: Date.now() });
179	    await this.saveState(state);
180	    return { reply, state };
181	  }
182	
183	  /** Not every thrown error should end the conversation:
184	   * - AI-layer hiccups (transient Workers AI errors, exhausted) aren't
185	   *   business failures at all — stay exactly where we were.
186	   * - A *retryable* HOFJ error (429/502/503) hit during search/discovery,
187	   *   before any real cart exists, is also worth surviving — the
188	   *   traveller hasn't committed to anything yet, so failing the whole
189	   *   conversation over a rate limit blip is worse than just asking them
190	   *   to try again. Only a genuinely fatal failure inside the real
191	   *   booking pipeline (handled explicitly in attemptPayment /
192	   *   confirmPaymentAndBook, which set stage="failed" themselves with a
193	   *   specific reason) should be terminal. */
194	  private async handleUnexpectedError(state: ConversationState, err: unknown): Promise<string> {
195	    if (err instanceof AiUnavailableError) {
196	      return "Scusa, non ho capito bene — puoi ripetere?";
197	    }
198	    if (err instanceof HofjApiError && err.retryable) {
199	      return "Il sistema è un po' lento in questo momento, puoi ripetere?";
200	    }
201	    state.stage = "failed";
202	    state.failureReason = err instanceof Error ? err.message : String(err);
203	    return "Mi dispiace, ho un problema tecnico interno e non posso continuare questa conversazione. Riprova più tardi aprendone una nuova.";
204	  }
205	
206	  /** Human-readable description of what the *previous* agent turn was
207	   * actually asking about, fed to interpret() so it can disambiguate a
208	   * short, context-free answer (e.g. "Milano" alone) — see the
209	   * "city" collision doc in engine/ai.ts. Based on state as it stands
210	   * before this turn's own updates, i.e. what was truly just asked. */
211	  private describeCurrentlyAsking(state: ConversationState): string | null {
212	    if (state.stage === "collecting") {
213	      const labels: Partial<Record<(typeof REQUIRED_TRIP_SLOTS)[number], string>> = {
214	        sport: "che sport vuole praticare",
215	        city: "in che città o zona vuole andare in vacanza (la destinazione del viaggio)",
216	        dateFrom: "quando vuole partire",
217	        budget: "il budget",
218	        adults: "in quante persone viaggia",
219	      };
220	      for (const key of REQUIRED_TRIP_SLOTS) {
221	        if (!this.isGatingSatisfied(state, key)) return labels[key] ?? key;
222	      }
223	      return null;
224	    }
225	    if (state.stage === "proposing") {
226	      return "se conferma o rifiuta la proposta di viaggio appena fatta";
227	    }
228	    if (state.stage === "collecting_traveller") {
229	      const labels: Partial<Record<keyof TravellerInfo, string>> = {
230	        firstName: "il nome del viaggiatore",
231	        lastName: "il cognome del viaggiatore",
232	        email: "l'email del viaggiatore",
233	        phone: "il telefono del viaggiatore",
234	        city: "la città DI RESIDENZA del viaggiatore, per l'indirizzo di fatturazione — NON la destinazione del viaggio, quella è già decisa",
235	      };
236	      const missing = REQUIRED_TRAVELLER_FIELDS.find((f) => state.traveller[f] === null);
237	      return missing ? (labels[missing] ?? missing) : null;
238	    }
239	    return null;
240	  }
241	
242	  /** Is this required slot resolved enough to stop gating the search?
243	   * "Resolved" isn't only "has a literal value" — city and dateFrom can
244	   * also be satisfied by giving up on precision (a persisted vague date,
245	   * or enough failed city asks), and budget the same way once it's had
246	   * its one ask. adults is the deliberate exception: only a real value
247	   * counts, ever — see ARCHITECTURE.md, Giuseppe's explicit line that
248	   * budget and party size are the two that are never decided for the
249	   * traveller. (Budget itself moved off that hard line in a later
250	   * revision — adults is now the only one still on it.) */
251	  private isGatingSatisfied(state: ConversationState, key: (typeof REQUIRED_TRIP_SLOTS)[number]): boolean {
252	    switch (key) {
253	      case "dateFrom":
254	        return state.slots.dateFrom !== null || state.slots.dateFromVague !== null;
255	      case "city":
256	        return state.slots.city !== null || state.cityAskAttempts >= CITY_LOOP_BREAKER;
257	      case "budget":
258	        return state.slots.budget !== null || state.slots.budgetTier !== null || state.budgetAskAttempts >= BUDGET_LOOP_BREAKER;
259	      default:
260	        return state.slots[key] !== null;
261	    }
262	  }
263	
264	  private async runCollecting(state: ConversationState): Promise<string> {
265	    // Walk the required slots in order and ask about the first one that
266	    // isn't gating-satisfied yet. Critically, a bypass on one slot (e.g. a
267	    // vague date accepted) does NOT jump straight to search — it only
268	    // clears that one slot's gate, so a still-missing, never-bypassable
269	    // slot further down the list (adults) still gets asked. An earlier
270	    // version of this function short-circuited straight to
271	    // searchAndPropose() on any bypass, which silently skipped asking
272	    // about adults whenever it happened to come after a bypassed slot —
273	    // found reading the code, not guessed: verified live that a
274	    // conversation reached "proposing" with adults still null.
275	    for (const key of REQUIRED_TRIP_SLOTS) {
276	      if (this.isGatingSatisfied(state, key)) continue;
277	      if (key === "city") state.cityAskAttempts += 1;
278	      if (key === "budget") state.budgetAskAttempts += 1;
279	      return say(this.env, { kind: "ask_slot", missing: key });
280	    }
281	    return this.searchAndPropose(state);
282	  }
283	
284	  /** `precededBy` folds a one-line acknowledgment of why we're searching
285	   * again into the SAME proposal message ("quel pacchetto non risulta più
286	   * disponibile, però ho trovato quest'altro...") instead of a separate
287	   * filler turn. */
288	  private async searchAndPropose(
289	    state: ConversationState,
290	    precededBy?: "rejected" | "unavailable",
291	  ): Promise<string> {
292	    const { candidates, locationMatched } = await searchCandidates(this.hofj, state.slots);
293	    const ctx = classify(state.slots, candidates, state.rejectedProductIds, locationMatched);
294	    if (!ctx) {
295	      state.stage = "collecting";
296	      return say(this.env, { kind: "no_match" });
297	    }
298	    state.cityAskAttempts = 0;
299	    state.budgetAskAttempts = 0;
300	    state.proposal = ctx;
301	    state.stage = "proposing";
302	    return say(this.env, { kind: "propose", ctx, precededBy });
303	  }
304	
305	  private async runProposing(state: ConversationState, decision: "yes" | "no" | "unclear"): Promise<string> {
306	    if (decision === "yes" && state.proposal) {
307	      // The traveller never gave a specific date (date_unspecified
308	      // compromise) — commit to the candidate's own earliest availability
309	      // now that they've confirmed it, so the real booking call further
310	      // down the pipeline has a startDate to send. Only fires when
311	      // dateFrom is still null, so it never overwrites a date the
312	      // traveller actually gave.
313	      if (state.slots.dateFrom === null) {
314	        state.slots.dateFrom = state.proposal.candidate.minDate;
315	        state.slots.dateFromVague = null;
316	      }
317	      state.stage = "collecting_traveller";
318	      // Traveller info may already be filled from an earlier attempt (e.g.
319	      // a price-changed re-confirmation loop) — don't re-ask what we
320	      // already have, go straight to opening the cart if it's complete.
321	      return this.runCollectingTraveller(state);
322	    }
323	    if (decision === "no" && state.proposal) {
324	      state.rejectedProductIds.push(state.proposal.candidate.productId);
325	      state.proposal = null;
326	      return this.searchAndPropose(state, "rejected");
327	    }
328	    // "unclear" -> re-evaluate in case the traveller changed a slot
329	    // (budget/date/city) without an explicit yes/no.
330	    return this.searchAndPropose(state);
331	  }
332	
333	  private async runCollectingTraveller(state: ConversationState): Promise<string> {
334	    const missing = REQUIRED_TRAVELLER_FIELDS.find((f) => state.traveller[f] === null);
335	    if (missing) {
336	      const isFirstAsk = REQUIRED_TRAVELLER_FIELDS.every((f) => state.traveller[f] === null);
337	      return say(this.env, { kind: "ask_traveller_field", field: missing, isFirstAsk });
338	    }
339	    return this.openRealCartAndAttemptPayment(state);
340	  }
341	
342	  /** The real, money-real part of the pipeline: opens an actual HOFJ cart,
343	   * silently re-verifies price against the live snapshot, writes real
344	   * traveller data, then tries to get a Stripe payment intent. */
345	  private async openRealCartAndAttemptPayment(state: ConversationState): Promise<string> {
346	    const proposal = state.proposal!;
347	    const { candidate } = proposal;
348	    const requestedDate = state.slots.dateFrom!;
349	    // A single room only fits so many people — verified live: 3 adults
350	    // with rooms:1 on a real product 400ed upstream with
351	    // ComponentAvailability ("lack of availability"), and passing rooms:2
352	    // fixed it immediately. Two people per room is a standard hotel
353	    // convention and a reasonable default absent a way to ask the
354	    // traveller directly without adding a whole new slot-filling step for
355	    // room configuration, which is out of scope here.
356	    const rooms = Math.max(1, Math.ceil(state.slots.adults! / 2));
357	
358	    let created;
359	    try {
360	      created = await this.hofj.createItinerary({
361	        productId: candidate.productId,
362	        startDate: requestedDate,
363	        adults: state.slots.adults!,
364	        rooms,
365	      });
366	    } catch (err) {
367	      if (err instanceof HofjApiError) {
368	        console.error("createItinerary failed:", err.status, err.detail.slice(0, 200));
369	      }
370	      // minDate/maxDate from search is a *range*, but real availability is
371	      // discrete slots inside it — verified live: a date well within that
372	      // range still fails upstream with RESERVATION_PERIOD_ERROR. Treating
373	      // this as a generic transient error would tell the traveller "the
374	      // system is slow, try again" — misleading, since retrying the exact
375	      // same date is guaranteed to fail identically. We can't reliably
376	      // string-match the specific upstream reason: verified live that the
377	      // real detail sometimes arrives intact via HofjApiError, but other
378	      // times arrives collapsed to a generic "error code: 502" — Cloudflare
379	      // itself appears to synthesize that when HOFJ's origin misbehaves on
380	      // this response, before our own JSON-parsing fallback ever sees the
381	      // real body. So instead of gating on the exact error text, treat ANY
382	      // createItinerary failure as "this date probably isn't real" and
383	      // negotiate: fall back to the candidate's own minDate (near-certain
384	      // to be a real slot, since every product tested this session opened
385	      // successfully on it) and ask for reconfirmation, same pattern as a
386	      // price/date compromise. Only skip this when we're already on
387	      // minDate (nothing left to fall back to — a genuinely different,
388	      // fatal problem at that point).
389	      if (err instanceof HofjApiError && requestedDate !== candidate.minDate) {
390	        state.slots.dateFrom = candidate.minDate;
391	        state.stage = "proposing";
392	        state.proposal = {
393	          ...proposal,
394	          category: "compromise",
395	          compromise: { kind: "date", requested: requestedDate, offered: candidate.minDate },
396	        };
397	        return say(this.env, { kind: "propose", ctx: state.proposal });
398	      }
399	      // Already on the candidate's own known-good minDate and it *still*
400	      // failed: this isn't a date problem, and retrying (the generic
401	      // "sistema lento, riprova" path) can never succeed — verified live,
402	      // this exact product/date/party-size combo 404ed upstream with
403	      // NOT_FOUND_ERROR even though it came back as a normal, well-formed
404	      // search result. Exactly the "prodotto non prenotabile" case the
405	      // brief warns about, just discovered at booking time instead of
406	      // search time. Reject this specific product and look for the next
407	      // best candidate instead of asking the traveller to retry something
408	      // that will never work.
409	      if (err instanceof HofjApiError) {
410	        state.rejectedProductIds.push(candidate.productId);
411	        state.proposal = null;
412	        state.stage = "collecting";
413	        return this.searchAndPropose(state, "unavailable");
414	      }
415	      throw err;
416	    }
417	    state.itineraryId = created.data.itineraryId;
418	
419	    const snapshot = await this.hofj.getItinerary(state.itineraryId);
420	    const livePrice = Number(snapshot.data.totalPrice.amount);
421	    const proposedPrice = candidate.price;
422	    if (Math.abs(livePrice - proposedPrice) / proposedPrice > PRICE_CHANGE_TOLERANCE) {
423	      state.proposal = {
424	        ...proposal,
425	        candidate: { ...candidate, price: livePrice },
426	        category: "compromise",
427	        compromise: { kind: "price", requested: `${proposedPrice}€`, offered: `${livePrice}€` },
428	      };
429	      state.stage = "proposing";
430	      return say(this.env, {
431	        kind: "price_changed",
432	        oldPrice: `${proposedPrice}€`,
433	        newPrice: `${livePrice}€`,
434	      });
435	    }
436	    state.totalPrice = snapshot.data.totalPrice;
437	
438	    const traveller = state.traveller;
439	    await this.hofj.putCustomer(state.itineraryId, {
440	      firstName: traveller.firstName!,
441	      lastName: traveller.lastName!,
442	      email: traveller.email!,
443	      phone: traveller.phone!,
444	      address: {
445	        street1: "N/A",
446	        postalCode: traveller.postalCode ?? "00000",
447	        city: traveller.city!,
448	        region: "",
449	        countryCode: traveller.countryCode ?? candidate.country,
450	      },
451	    });
452	    await this.hofj.putPax(state.itineraryId, [
453	      { refId: "pax-1", firstName: traveller.firstName!, lastName: traveller.lastName! },
454	    ]);
455	
456	    return this.attemptPayment(state);
457	  }
458	
459	  private async attemptPayment(state: ConversationState): Promise<string> {
460	    try {
461	      await this.hofj.getPaymentIntent(state.itineraryId!);
462	      // Would hand the client_secret to the frontend for Stripe.js here;
463	      // left for confirmPaymentAndBook() to be invoked once Stripe confirms
464	      // client-side. See ARCHITECTURE.md — untestable while the upstream
465	      // payment endpoint 502s, kept spec-correct for when it recovers.
466	      state.stage = "paying";
467	      return say(this.env, { kind: "payment_unavailable", retrying: true });
468	    } catch (err) {
469	      state.stage = "failed";
470	      state.failureReason = err instanceof HofjApiError ? `payment: ${err.message}` : String(err);
471	      return say(this.env, { kind: "payment_unavailable", retrying: false });
472	    }
473	  }
474	
475	  /** Invoked by the frontend once Stripe.js confirms the card payment
476	   * client-side. Currently unreachable in practice — attemptPayment() never
477	   * reaches "paying" while GET .../payment 502s — but implemented to spec
478	   * so the last mile just works the moment that upstream bug is fixed. */
479	  async confirmPaymentAndBook(): Promise<HandleMessageResult> {
480	    const state = await this.loadState();
481	    if (state.stage !== "paying" || !state.itineraryId) {
482	      const reply = "Non c'è un pagamento in corso da confermare per questa conversazione.";
483	      return { reply, state };
484	    }
485	    let reply: string;
486	    try {
487	      const booking = await this.hofj.confirmBooking(state.itineraryId);
488	      state.stage = "booked";
489	      state.reservationCode = booking.data;
490	      reply = await say(this.env, {
491	        kind: "booked",
492	        reservationCode: booking.data,
493	        title: state.proposal!.candidate.title,
494	        totalPrice: `${state.totalPrice!.amount}${state.totalPrice!.currency === "EUR" ? "€" : " " + state.totalPrice!.currency}`,
495	        startDate: state.slots.dateFrom!,
496	      });
497	    } catch (err) {
498	      state.stage = "failed";
499	      if (err instanceof HofjApiError && err.status === 403) {
500	        state.failureReason = "bookings: 403 forbidden-entity";
501	        reply = await say(this.env, { kind: "booking_forbidden" });
502	      } else {
503	        state.failureReason = err instanceof Error ? err.message : String(err);
504	        reply = await say(this.env, { kind: "payment_unavailable", retrying: false });
505	      }
506	    }
507	    state.messages.push({ role: "agent", text: reply, at: Date.now() });
508	    await this.saveState(state);
509	    return { reply, state };
510	  }
511	}
