import { describe, expect, it } from "vitest";
import { extractMonthHint, resolveDate } from "../src/engine/dates";

// Fixed "now" so tests don't depend on the day they're run.
const NOW = new Date("2026-09-14T10:00:00.000Z");

describe("resolveDate", () => {
  it("returns null for no input", () => {
    expect(resolveDate(null, NOW)).toBeNull();
  });

  it("passes through an already-ISO date", () => {
    expect(resolveDate("2026-12-25", NOW)).toBe("2026-12-25");
  });

  it("resolves 'oggi' / 'domani' / 'dopodomani'", () => {
    expect(resolveDate("oggi", NOW)).toBe("2026-09-14");
    expect(resolveDate("domani", NOW)).toBe("2026-09-15");
    expect(resolveDate("dopodomani", NOW)).toBe("2026-09-16");
  });

  it("resolves a day+month phrase to the current year when still in the future", () => {
    expect(resolveDate("il 25 settembre", NOW)).toBe("2026-09-25");
  });

  it("rolls over to next year when the day+month has already passed this year", () => {
    // "now" is 2026-09-14, so March 1st this year is in the past.
    expect(resolveDate("1 marzo", NOW)).toBe("2027-03-01");
  });

  it("never falls back to an epoch/placeholder year (regression: live Workers AI returned 1970)", () => {
    const resolved = resolveDate("il 25 settembre", NOW);
    expect(resolved).not.toMatch(/^19/);
  });

  it("resolves an explicit year when given", () => {
    expect(resolveDate("25 settembre 2028", NOW)).toBe("2028-09-25");
  });

  it("resolves 'tra N giorni' / 'tra N settimane'", () => {
    expect(resolveDate("tra 10 giorni", NOW)).toBe("2026-09-24");
    expect(resolveDate("tra 2 settimane", NOW)).toBe("2026-09-28");
  });

  it("resolves 'il prossimo weekend' to the next Saturday", () => {
    // NOW is 2026-09-14, a Monday.
    expect(resolveDate("il prossimo weekend", NOW)).toBe("2026-09-19");
  });

  it("returns null for unparseable free text rather than guessing", () => {
    expect(resolveDate("appena possibile", NOW)).toBeNull();
  });

  it("handles 'di' as a connector between day and month (regression: live user said \"il 9 di ottobre\" twice, both silently dropped)", () => {
    expect(resolveDate("il 9 di ottobre", NOW)).toBe("2026-10-09");
    expect(resolveDate("9 di ottobre", NOW)).toBe("2026-10-09");
  });

  it("resolves a slash-separated DD/MM/YYYY date, Italian convention not US (regression: live user typed \"9/10/2026\", silently dropped)", () => {
    expect(resolveDate("9/10/2026", NOW)).toBe("2026-10-09");
    expect(resolveDate("09-10-2026", NOW)).toBe("2026-10-09");
  });

  it("resolves English month names too, both day-before and day-after orderings (regression: live 'three days off in June' request was in English)", () => {
    expect(resolveDate("September 25th", NOW)).toBe("2026-09-25");
    expect(resolveDate("25 September", NOW)).toBe("2026-09-25");
    expect(resolveDate("October 9, 2027", NOW)).toBe("2027-10-09");
  });

  it("resolves English relative dates: today/tomorrow/next weekend/in N days", () => {
    expect(resolveDate("today", NOW)).toBe("2026-09-14");
    expect(resolveDate("tomorrow", NOW)).toBe("2026-09-15");
    expect(resolveDate("next weekend", NOW)).toBe("2026-09-19");
    expect(resolveDate("in 10 days", NOW)).toBe("2026-09-24");
  });
});

describe("extractMonthHint", () => {
  it("returns null for no input or text without a month", () => {
    expect(extractMonthHint(null)).toBeNull();
    expect(extractMonthHint("as soon as possible")).toBeNull();
  });

  it("extracts a bare month reference in Italian and English, without needing a day (regression: 'in June' with no day was previously lost entirely)", () => {
    expect(extractMonthHint("in June")).toBe(6);
    expect(extractMonthHint("a giugno")).toBe(6);
    expect(extractMonthHint("three days off in June")).toBe(6);
    expect(extractMonthHint("verso ottobre")).toBe(10);
  });

  it("also extracts the month from a phrase that includes a day (resolveDate handles the day; this is just the month signal)", () => {
    expect(extractMonthHint("September 25th")).toBe(9);
  });
});

import type { Env } from "../types";

export class StripeApiError extends Error {
  constructor(
    public status: number,
    detail: string,
  ) {
    super(`Stripe ${status}: ${detail}`);
    this.name = "StripeApiError";
  }
}

interface PaymentIntent {
  id: string;
  client_secret: string;
  status: string;
}

async function request(env: Env, path: string, params: Record<string, string>): Promise<PaymentIntent> {
  if (!env.STRIPE_SECRET_KEY) throw new StripeApiError(0, "STRIPE_SECRET_KEY not configured");
  const res = await fetch(`https://api.stripe.com/v1${path}`, {
    method: "POST",
    headers: {
      // Stripe accepts the secret key as the HTTP Basic username with an
      // empty password — same as every official Stripe client library.
      Authorization: `Basic ${btoa(`${env.STRIPE_SECRET_KEY}:`)}`,
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body: new URLSearchParams(params),
  });
  const json = await res.json<PaymentIntent & { error?: { message?: string } }>();
  if (!res.ok) throw new StripeApiError(res.status, json.error?.message ?? res.statusText);
  return json;
}

/** Creates a real Stripe PaymentIntent directly against HOFJ's own Stripe
 * account — confirmed by Vela (Carlo, 2026-09-15) as the sanctioned bypass
 * for their own broken GET .../payment endpoint, not a workaround we
 * invented unilaterally. `metadata.checkoutRefId = itineraryId` is the
 * exact key HOFJ's own backend uses internally (verified live: found 38
 * real succeeded PaymentIntents in this same account with that precise
 * metadata shape before writing this). See ARCHITECTURE.md. */
export async function createPaymentIntent(
  env: Env,
  params: { amountMinorUnits: number; currency: string; itineraryId: string },
): Promise<PaymentIntent> {
  return request(env, "/payment_intents", {
    amount: String(params.amountMinorUnits),
    currency: params.currency.toLowerCase(),
    "payment_method_types[]": "card",
    "metadata[checkoutRefId]": params.itineraryId,
  });
}

/** Confirms with Stripe's own official test card token. Deliberate demo
 * simplification, documented as such in ARCHITECTURE.md: a real
 * production flow hands the client_secret to the frontend for Stripe
 * Elements / the actual cardholder to confirm — the Worker should never
 * touch real card details. There's no Stripe.js integration in this
 * prototype's frontend, so this is how the payment step gets proven to
 * work for real, in test mode, without building that UI under time
 * pressure. */
export async function confirmPaymentIntent(env: Env, paymentIntentId: string): Promise<PaymentIntent> {
  return request(env, `/payment_intents/${paymentIntentId}/confirm`, {
    payment_method: "pm_card_visa",
  });
}

import type { Env } from "../types";

export class HofjApiError extends Error {
  constructor(
    public status: number,
    public detail: string,
    public retryable: boolean,
  ) {
    super(`HOFJ ${status}: ${detail}`);
    this.name = "HofjApiError";
  }
}

export interface SearchProduct {
  productId: number;
  title: string;
  price: number;
  currency: string;
  primaryCategory: string;
  primaryDestination: string;
  primaryVenue?: string;
  country: string;
  minDate: string;
  maxDate: string;
  defaultDurationInDays: number;
}

export interface SearchResponse {
  data: { total: number; products: SearchProduct[] };
}

export interface CreateItineraryResponse {
  data: { itineraryId: string };
}

export interface ItinerarySnapshot {
  data: {
    productId: string;
    title: string;
    titleVenue: string;
    totalPrice: { amount: string; currency: string };
    startDate: string;
    endDate: string;
    checkout: { status: string; total: { amount: string; currency: string } };
  };
}

export interface CustomerPayload {
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  address: {
    street1: string;
    postalCode: string;
    city: string;
    region: string;
    countryCode: string;
  };
}

export interface PaxPayload {
  refId: string;
  firstName?: string;
  lastName?: string;
}

/** Thin, typed wrapper over the House of Journeys distribution API.
 * Retries transient upstream failures (429/502/503) once with backoff;
 * surfaces permission/config errors (401/403/400) immediately since those
 * are never fixed by retrying. */
export class HofjClient {
  private readonly base: string;
  private readonly brand: string;
  private readonly locale: string;
  private readonly key: string;

  constructor(env: Env) {
    this.base = env.HOFJ_BASE_URL;
    this.brand = env.HOFJ_BRAND;
    this.locale = env.HOFJ_LOCALE;
    this.key = env.HOFJ_API_KEY;
  }

  private async request<T>(
    method: string,
    path: string,
    opts: {
      query?: Record<string, string | number | undefined>;
      body?: unknown;
      brand?: string;
      /** Set for any POST that isn't a documented upsert — retrying a
       * transient error on a true "create" call risks leaving a second,
       * orphaned resource behind if the first attempt actually succeeded
       * server-side and only the response was lost. POST /v1/itineraries
       * is exactly that case (spec: "Create a new itinerary"); POST
       * /v1/bookings is explicitly documented as an upsert keyed by
       * itineraryId, so it stays safe to retry. */
      noRetry?: boolean;
    } = {},
  ): Promise<T> {
    const url = new URL(this.base + path);
    url.searchParams.set("brand", opts.brand ?? this.brand);
    url.searchParams.set("locale", this.locale);
    for (const [k, v] of Object.entries(opts.query ?? {})) {
      if (v !== undefined) url.searchParams.set(k, String(v));
    }

    const doFetch = () =>
      fetch(url, {
        method,
        headers: {
          Authorization: `Bearer ${this.key}`,
          ...(opts.body ? { "Content-Type": "application/json" } : {}),
        },
        body: opts.body ? JSON.stringify(opts.body) : undefined,
      });

    let res = await doFetch();
    if (!opts.noRetry && (res.status === 429 || res.status === 502 || res.status === 503)) {
      await new Promise((r) => setTimeout(r, 400));
      res = await doFetch();
    }

    if (!res.ok) {
      // Read as text first, then try to parse: verified live that
      // res.json() can throw here even though the exact same response body
      // is valid JSON when fetched with curl directly (large error bodies
      // with escaped stack traces — worth having the raw text either way,
      // since a parse failure previously collapsed the real upstream
      // detail down to a useless generic "Bad Gateway").
      const raw = await res.text().catch(() => "");
      let detail = raw || res.statusText;
      try {
        const problem = JSON.parse(raw) as { detail?: string; title?: string };
        detail = problem.detail ?? problem.title ?? detail;
      } catch {
        // not JSON (or empty) — keep the raw text as the detail
      }
      const retryable = res.status === 429 || res.status === 502 || res.status === 503;
      throw new HofjApiError(res.status, detail, retryable);
    }
    return res.json<T>();
  }

  search(params: {
    keyword?: string;
    destination?: string;
    category?: string;
    priceMax?: number;
    dateFrom?: string;
    dateTo?: string;
    topN?: number;
    brand?: string;
  }): Promise<SearchResponse> {
    return this.request("GET", "/v1/recommendations/search", {
      brand: params.brand,
      query: {
        keyword: params.keyword,
        destination: params.destination,
        category: params.category,
        price_max: params.priceMax,
        date_from: params.dateFrom,
        date_to: params.dateTo,
        top_n: params.topN ?? 5,
      },
    });
  }

  createItinerary(input: {
    productId: number | string;
    startDate: string;
    adults: number;
    rooms: number;
  }): Promise<CreateItineraryResponse> {
    // The OpenAPI spec documents productId as oneOf(integer, string), but
    // the actual brand-site upstream (verified live) enforces a strict Zod
    // number check and 400s on a numeric string. Always coerce.
    return this.request("POST", "/v1/itineraries", {
      body: { ...input, productId: Number(input.productId), currency: "EUR" },
      noRetry: true, // creates a new cart each call — see request()'s noRetry doc
    });
  }

  getItinerary(itineraryId: string): Promise<ItinerarySnapshot> {
    return this.request("GET", `/v1/itineraries/${itineraryId}`);
  }

  putCustomer(itineraryId: string, customer: CustomerPayload): Promise<void> {
    return this.request("PUT", `/v1/itineraries/${itineraryId}/customer`, { body: customer });
  }

  putPax(itineraryId: string, pax: PaxPayload[]): Promise<void> {
    return this.request("PUT", `/v1/itineraries/${itineraryId}/pax`, { body: pax });
  }

  /** Refresh the Stripe PaymentIntent and return its client_secret.
   * Known-broken upstream as of 2026-09-14 (502, upstream 405) — see
   * ARCHITECTURE.md. Kept spec-correct so it starts working the moment the
   * upstream bug is fixed, since HOFJ's inventory/backend is shared and can
   * change during the session. */
  getPaymentIntent(itineraryId: string): Promise<{ data: string }> {
    return this.request("GET", `/v1/itineraries/${itineraryId}/payment`);
  }

  /** Confirm the booking after Stripe payment succeeds. `paymentType` is
   * undocumented in the OpenAPI spec (which lists only itineraryId) but
   * required by the actual upstream — "full" (pay everything now) or
   * "plan" (deposit + balance, per-product). Known-broken as of
   * 2026-09-15: verified live that the gateway drops this field entirely
   * before forwarding it (identical ZodError with either value) — see
   * ARCHITECTURE.md. Sent anyway, spec-correct, for when that's fixed. */
  confirmBooking(itineraryId: string, paymentType: "full" | "plan" = "full"): Promise<{ data: string }> {
    return this.request("POST", "/v1/bookings", { body: { itineraryId, paymentType } });
  }

  getQuota(): Promise<{ data: { remainingInWindow: number; limitPerMinute: number } }> {
    return this.request("GET", "/v1/quota");
  }
}

