1	import type { HofjClient, SearchProduct } from "../hofj/client";
2	import type { Candidate, ConfidenceCategory, ProposalContext, Slots } from "../types";
3	
4	/** Budget beyond which we stop calling it a "compromise" and ask a
5	 * clarifying question instead of proposing an unreasonably priced trip. */
6	const BUDGET_COMPROMISE_CEILING = 2.0;
7	const DATE_COMPROMISE_WINDOW_DAYS = 45;
8	
9	function toCandidate(p: SearchProduct): Candidate {
10	  return {
11	    productId: String(p.productId),
12	    title: p.title,
13	    venue: p.primaryVenue ?? p.primaryDestination,
14	    city: p.primaryDestination,
15	    country: p.country,
16	    price: p.price,
17	    currency: p.currency,
18	    minDate: p.minDate,
19	    maxDate: p.maxDate,
20	    durationDays: p.defaultDurationInDays,
21	  };
22	}
23	
24	function daysBetween(a: string, b: string): number {
25	  return Math.abs(new Date(a).getTime() - new Date(b).getTime()) / 86_400_000;
26	}
27	
28	function pad2(n: number): string {
29	  return String(n).padStart(2, "0");
30	}
31	
32	/** First date within [minDate, maxDate] that falls in the given month
33	 * (1-12), checking every year the range spans — a product's availability
34	 * window can cross a year boundary. Null if the month never overlaps the
35	 * range at all. Used so a preferred month actually influences which date
36	 * gets offered, instead of always defaulting to the range's own start
37	 * (regression: live "three days off in June" got offered a December date
38	 * because nothing looked at the month at all). */
39	function firstDateInMonth(minDate: string, maxDate: string, month: number): string | null {
40	  const start = new Date(`${minDate}T00:00:00Z`);
41	  const end = new Date(`${maxDate}T00:00:00Z`);
42	  for (let year = start.getUTCFullYear(); year <= end.getUTCFullYear(); year++) {
43	    const monthStart = new Date(Date.UTC(year, month - 1, 1));
44	    const monthEnd = new Date(Date.UTC(year, month, 0)); // last day of that month
45	    const overlapStart = monthStart > start ? monthStart : start;
46	    const overlapEnd = monthEnd < end ? monthEnd : end;
47	    if (overlapStart <= overlapEnd) {
48	      return `${overlapStart.getUTCFullYear()}-${pad2(overlapStart.getUTCMonth() + 1)}-${pad2(overlapStart.getUTCDate())}`;
49	    }
50	  }
51	  return null;
52	}
53	
54	/** Deterministic, auditable match classification — no invented numeric
55	 * scores. Business logic lives here so it can be unit-tested without the
56	 * AI binding; the AI's job is only to phrase the result (see engine/ai.ts).
57	 * `locationMatched` (from searchCandidates) is false when the proposal is
58	 * in a city the traveller didn't specifically ask for — either because
59	 * they never gave one, or gave one nothing matched — which always gets
60	 * flagged as a compromise, same policy as an unspecified date: the agent
61	 * may decide, but never silently. */
62	export function classify(
63	  slots: Slots,
64	  candidates: SearchProduct[],
65	  rejectedProductIds: string[],
66	  locationMatched: boolean,
67	): ProposalContext | null {
68	  let pool = candidates.filter((c) => !rejectedProductIds.includes(String(c.productId)));
69	  if (pool.length === 0) return null;
70	
71	  // A preferred month (from a vague date like "in June" that didn't
72	  // resolve to an exact day) doesn't hard-filter — a near-miss candidate
73	  // is still worth a compromise, same reasoning as an exact date mismatch
74	  // below — but it should outrank candidates with no relation to that
75	  // month at all, so classify() doesn't pick something available only in
76	  // a completely different season.
77	  if (slots.dateFrom === null && slots.preferredMonth !== null) {
78	    const month = slots.preferredMonth;
79	    const matching = pool.filter((c) => firstDateInMonth(c.minDate, c.maxDate, month) !== null);
80	    if (matching.length > 0) pool = [...matching, ...pool.filter((c) => !matching.includes(c))];
81	  }
82	
83	  // Which candidate to propose: normally the API's own top-ranked
84	  // (relevance/combinedScore) result. When the traveller wants cheap —
85	  // either because they never gave a budget at all, or said so
86	  // qualitatively ("economico") — relevance ranking isn't the right
87	  // tiebreaker for something being chosen FOR them; pick the cheapest in
88	  // the pool instead, so any disclosed compromise is honest about what
89	  // "cheapest" actually means rather than an arbitrary ranking artifact.
90	  // "mid" ("carino ma non troppo caro") isn't the cheapest OR an
91	  // unconstrained pick either — the median price in the pool is a
92	  // defensible reading of "reasonable, not the bargain bin, not the
93	  // splurge", better than either extreme.
94	  const wantsCheapest = slots.budget === null && (slots.budgetTier === null || slots.budgetTier === "low");
95	  const wantsMid = slots.budget === null && slots.budgetTier === "mid";
96	  const best = wantsCheapest
97	    ? pool.reduce((min, c) => (c.price < min.price ? c : min), pool[0]!)
98	    : wantsMid
99	      ? [...pool].sort((a, b) => a.price - b.price)[Math.floor(pool.length / 2)]!
100	      : pool[0]!;
101	  const candidate = toCandidate(best);
102	
103	  let category: ConfidenceCategory = "exact";
104	  let compromise: ProposalContext["compromise"] = null;
105	
106	  if (slots.budget !== null) {
107	    if (candidate.price > slots.budget * BUDGET_COMPROMISE_CEILING) {
108	      return null; // too far off to call it a reasonable proposal
109	    }
110	    if (candidate.price > slots.budget) {
111	      category = "compromise";
112	      compromise = {
113	        kind: "price",
114	        requested: `${slots.budget}€`,
115	        offered: `${candidate.price}${candidate.currency === "EUR" ? "€" : " " + candidate.currency}`,
116	      };
117	    }
118	  } else if (slots.budgetTier === null) {
119	    // Never mentioned budget at all, not even qualitatively — same
120	    // discipline as date_unspecified: propose the cheapest relevant
121	    // option, but always as a disclosed compromise, never silently.
122	    category = "compromise";
123	    compromise = {
124	      kind: "budget_unspecified",
125	      requested: "",
126	      offered: `${candidate.price}${candidate.currency === "EUR" ? "€" : " " + candidate.currency}`,
127	    };
128	    // budgetTier "low"/"mid"/"high" with no numeric budget: an explicit
129	    // qualitative answer was given and is satisfied by construction
130	    // (selection above already picked cheapest/median/default
131	    // accordingly) — no compromise needed for the budget dimension itself.
132	  }
133	
134	  if (!locationMatched && category !== "compromise") {
135	    category = "compromise";
136	    compromise = { kind: "location_unspecified", requested: slots.city ?? "", offered: candidate.city };
137	  }
138	
139	  if (slots.dateFrom !== null) {
140	    const inWindow = slots.dateFrom >= candidate.minDate && slots.dateFrom <= candidate.maxDate;
141	    if (!inWindow) {
142	      const nearest = slots.dateFrom < candidate.minDate ? candidate.minDate : candidate.maxDate;
143	      if (daysBetween(slots.dateFrom, nearest) > DATE_COMPROMISE_WINDOW_DAYS) {
144	        return null; // nearest availability too far from what was asked
145	      }
146	      // Price compromise (if any) stays the more salient one to mention;
147	      // otherwise lead with the date compromise.
148	      if (category !== "compromise") {
149	        category = "compromise";
150	        compromise = { kind: "date", requested: slots.dateFrom, offered: nearest };
151	      }
152	    }
153	  } else {
154	    // No date at all is not the same as a wrong date: a vague ask ("un
155	    // weekend a novembre", or simply nothing yet) shouldn't block a
156	    // proposal the way "collecting" used to (see ARCHITECTURE.md — live
157	    // regression where the dialogue just re-asked "when?" forever instead
