146	export type SayDirective =
147	  | { kind: "ask_slot"; missing: "sport" | "city" | "dateFrom" | "budget" | "adults" }
148	  | { kind: "propose"; ctx: ProposalContext; precededBy?: "rejected" | "unavailable" }
149	  | { kind: "ask_traveller_field"; field: keyof TravellerInfo; isFirstAsk: boolean }
150	  | { kind: "reverifying" }
151	  | { kind: "price_changed"; oldPrice: string; newPrice: string }
152	  | { kind: "payment_unavailable"; retrying: boolean }
153	  | { kind: "booking_forbidden" }
154	  | { kind: "booked"; reservationCode: string; title: string; totalPrice: string; startDate: string }
155	  | { kind: "no_match" };
