168	function directiveToInstruction(d: SayDirective): string {
169	  switch (d.kind) {
170	    case "ask_slot": {
171	      const labels: Record<typeof d.missing, string> = {
172	        sport: "che sport vuole praticare (tennis o padel)",
173	        city: "in che città o zona vuole andare",
174	        dateFrom: "quando vuole partire",
175	        budget: "qual è il budget indicativo",
176	        adults: "in quante persone viaggia",
177	      };
178	      return `Chiedi al viaggiatore, in una frase breve, ${labels[d.missing]}. Non chiedere altro insieme.`;
179	    }
180	    case "propose": {
181	      const { candidate, category, compromise } = d.ctx;
182	      const lead =
183	        d.precededBy === "rejected"
184	          ? "Il viaggiatore ha rifiutato la proposta precedente. Riconoscilo con una parola o due (non una frase intera a sé) e poi, nello stesso messaggio, "
185	          : d.precededBy === "unavailable"
186	            ? "Il pacchetto proposto prima non risulta più prenotabile per davvero (un problema del fornitore, non tuo). Diglielo in breve e poi, nello stesso messaggio, "
187	            : "";
188	      const base = `${lead}Proponi ESATTAMENTE questo pacchetto, uno solo: "${candidate.title}" a ${candidate.venue}, ${candidate.city}, prezzo ${candidate.price}${candidate.currency === "EUR" ? "€" : " " + candidate.currency}, ${candidate.durationDays} giorni, disponibile tra ${candidate.minDate} e ${candidate.maxDate}.`;
189	      if (category === "exact") return `${base} Corrisponde esattamente a quanto chiesto. Chiedi conferma per procedere.`;
