1	// Month names in the two languages we've verified live traffic in
2	// (Italian by default, English once language-mirroring kicked in — see
3	// ARCHITECTURE.md, 2026-09-15). Adding a language here is just adding a
4	// row; the rest of the resolver is language-agnostic regex plumbing.
5	const MONTHS: Record<string, number> = {
6	  gennaio: 1,
7	  january: 1,
8	  febbraio: 2,
9	  february: 2,
10	  marzo: 3,
11	  march: 3,
12	  aprile: 4,
13	  april: 4,
14	  maggio: 5,
15	  may: 5,
16	  giugno: 6,
17	  june: 6,
18	  luglio: 7,
19	  july: 7,
20	  agosto: 8,
21	  august: 8,
22	  settembre: 9,
23	  september: 9,
24	  ottobre: 10,
25	  october: 10,
26	  novembre: 11,
27	  november: 11,
28	  dicembre: 12,
29	  december: 12,
30	};
31	const MONTH_NAMES_PATTERN = Object.keys(MONTHS).join("|");
32	
33	function pad(n: number): string {
34	  return String(n).padStart(2, "0");
35	}
36	
37	function toIso(d: Date): string {
38	  return `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;
39	}
40	
41	function addDays(d: Date, days: number): Date {
42	  const copy = new Date(d);
43	  copy.setUTCDate(copy.getUTCDate() + days);
44	  return copy;
45	}
46	
47	/** Deterministic IT/EN date resolver. Calendar arithmetic is exactly the
48	 * kind of thing an LLM gets subtly wrong (verified live: Workers AI
49	 * Llama-3.3-70B returned "1970"/"1971" as the year despite an explicit
50	 * "today is 2026-09-14, never use 1970" instruction) — so the model is only
51	 * asked to lift the raw date phrase out of the sentence; resolving it to a
52	 * real calendar date happens here, in code, where it's testable. */
53	export function resolveDate(raw: string | null, now: Date = new Date()): string | null {
54	  if (!raw) return null;
55	  const text = raw.trim().toLowerCase();
56	
57	  const isoMatch = text.match(/(\d{4})-(\d{2})-(\d{2})/);
58	  if (isoMatch) return `${isoMatch[1]}-${isoMatch[2]}-${isoMatch[3]}`;
59	
60	  // "9/10/2026", "9-10-2026", "09.10.2026" — Italian/European convention
61	  // is day/month/year, not the US month/day/year (regression: "9/10/2026"
62	  // typed literally by a traveller was silently dropped, see
63	  // ARCHITECTURE.md for the live repro).
64	  const slashMatch = text.match(/\b(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{4})\b/);
65	  if (slashMatch) {
66	    const day = Number(slashMatch[1]);
67	    const month = Number(slashMatch[2]);
68	    const year = Number(slashMatch[3]);
69	    if (month >= 1 && month <= 12 && day >= 1 && day <= 31) {
70	      return toIso(new Date(Date.UTC(year, month - 1, day)));
71	    }
72	  }
73	
74	  if (/\boggi\b|\btoday\b/.test(text)) return toIso(now);
75	  if (/\bdomani\b|\btomorrow\b/.test(text)) return toIso(addDays(now, 1));
76	  if (/\bdopodomani\b|\bday after tomorrow\b/.test(text)) return toIso(addDays(now, 2));
77	
78	  const inDays = text.match(/tra\s+(\d+)\s+giorni|in\s+(\d+)\s+days?/);
79	  if (inDays) return toIso(addDays(now, Number(inDays[1] ?? inDays[2])));
80	  const inWeeks = text.match(/tra\s+(\d+)\s+settiman|in\s+(\d+)\s+weeks?/);
81	  if (inWeeks) return toIso(addDays(now, Number(inWeeks[1] ?? inWeeks[2]) * 7));
82	
83	  if (/prossimo\s+weekend|weekend\s+prossimo|prossimo\s+fine\s*settimana|next\s+weekend/.test(text)) {
84	    const day = now.getUTCDay(); // 0=Sun..6=Sat
85	    const offset = ((6 - day + 7) % 7) || 7; // next Saturday, always in the future
86	    return toIso(addDays(now, offset));
87	  }
88	
89	  // "25 settembre" / "il 9 di ottobre" / "September 25th" / "25 September
90	  // 2027" — "di"/"d'" as a connector is common spoken/written Italian
91	  // ("il 9 di ottobre"), and day-before-or-after-month covers both IT
92	  // ("25 settembre") and EN ("September 25th") orderings.
93	  const dayMonth = text.match(
94	    new RegExp(`(\\d{1,2})\\s*(?:°|º|st|nd|rd|th)?\\s*(?:di\\s+|d['’]\\s*|of\\s+)?(${MONTH_NAMES_PATTERN})(?:\\s+(\\d{4}))?`),
95	  );
96	  const monthDay = text.match(
97	    new RegExp(`(${MONTH_NAMES_PATTERN})\\s+(\\d{1,2})(?:st|nd|rd|th)?(?:,?\\s+(\\d{4}))?`),
98	  );
99	  const m = dayMonth ?? (monthDay && [monthDay[0], monthDay[2], monthDay[1], monthDay[3]]);
100	  if (m) {
101	    const day = Number(m[1]);
102	    const month = MONTHS[m[2]!.toLowerCase()]!;
103	    let year = m[3] ? Number(m[3]) : now.getUTCFullYear();
104	    let candidate = new Date(Date.UTC(year, month - 1, day));
105	    if (!m[3] && candidate.getTime() < Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate())) {
106	      year += 1;
107	      candidate = new Date(Date.UTC(year, month - 1, day));
108	    }
109	    return toIso(candidate);
110	  }
111	
112	  return null;
113	}
114	
115	/** Pulls a bare month reference ("in June", "a giugno", "verso ottobre")
116	 * out of a date phrase that didn't resolve to an exact day — used to bias
117	 * candidate selection toward the right month instead of blindly offering
118	 * the earliest availability regardless of season (regression: live test,
119	 * "three days off in June" got offered a December date because
120	 * date_unspecified only ever looked at candidate.minDate). Returns a bare
121	 * month number 1-12 — matcher.ts resolves which actual year/date within a
122	 * given candidate's availability window, since that depends on the
123	 * candidate, not on this phrase alone. */
124	export function extractMonthHint(raw: string | null): number | null {
