1	<!doctype html>
2	<html lang="it">
3	<head>
4	<meta charset="utf-8" />
5	<meta name="viewport" content="width=device-width, initial-scale=1" />
6	<title>Vela — agente di viaggio</title>
7	<style>
8	  :root {
9	    color-scheme: light dark;
10	    --bg: #0e1414;
11	    --panel: #161f1f;
12	    --accent: #7fd9a8;
13	    --text: #eef2ef;
