17	  body {
18	    margin: 0; min-height: 100vh; background: var(--bg); color: var(--text);
19	    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
20	    display: flex; flex-direction: column; align-items: center;
21	    padding: 24px 16px 40px;
22	  }
23	  main { width: 100%; max-width: 640px; }
24	  h1 { font-size: 1.1rem; font-weight: 600; margin: 0 0 4px; }
25	  p.tagline { color: var(--muted); font-size: 0.9rem; margin: 0 0 28px; }
