27	    display: flex; flex-direction: column; align-items: center; gap: 14px;
28	    padding: 32px 16px; margin-bottom: 20px;
29	  }
30	  #mic {
31	    width: 96px; height: 96px; border-radius: 50%; border: none;
32	    background: var(--panel); color: var(--accent);
33	    display: flex; align-items: center; justify-content: center;
34	    font-size: 2.2rem; cursor: pointer; transition: transform 0.15s, background 0.15s;
35	    box-shadow: 0 0 0 0 rgba(127,217,168,0.5);
36	  }
37	  #mic:active { transform: scale(0.96); }
38	  #mic.listening { background: var(--accent); color: #0e1414; animation: pulse 1.4s infinite; }
39	  #mic.speaking { background: #2a3a35; }
40	  @keyframes pulse {
41	    0% { box-shadow: 0 0 0 0 rgba(127,217,168,0.45); }
42	    70% { box-shadow: 0 0 0 18px rgba(127,217,168,0); }
43	    100% { box-shadow: 0 0 0 0 rgba(127,217,168,0); }
44	  }
45	  #status { color: var(--muted); font-size: 0.85rem; min-height: 1.2em; text-align: center; }
