59	  .msg { padding: 8px 12px; border-radius: 8px; max-width: 85%; font-size: 0.88rem; }
60	  .msg.traveller { align-self: flex-end; background: #1f2e29; }
61	  .msg.agent { align-self: flex-start; background: var(--panel); }
62	  .hint { font-size: 0.78rem; color: var(--muted); margin-top: -18px; margin-bottom: 24px; }
63	</style>
64	</head>
65	<body>
66	<main>
67	  <h1>Vela</h1>
68	  <p class="tagline">Non un sito di prenotazione: parlagli come parleresti a un umano. Padel, tennis, hotel — un'unica richiesta, in una frase.</p>
69	
70	  <div class="mic-stage">
71	    <button id="mic" aria-label="Parla con Vela">🎙️</button>
72	    <div id="status" aria-live="polite">Tocca il microfono e di' cosa vuoi</div>
73	    <div id="lastReply" aria-live="polite"></div>
74	  </div>
75	
76	  <form id="textForm">
77	    <input id="textInput" type="text" placeholder="…oppure scrivi qui se non puoi parlare ad alta voce" autocomplete="off" />
78	    <button class="send" type="submit">Invia</button>
79	  </form>
80	  <p class="hint">Il testo è un ripiego per chi non può usare la voce — l'interazione pensata è vocale, a schermo spento.</p>
81	
82	  <details>
83	    <summary>Trascrizione (per revisione)</summary>
84	    <div id="transcript" class="transcript"></div>
85	  </details>
86	</main>
87	
88	<script>
89	(function () {
90	  const SESSION_KEY = "vela.session.v1";
91	  let sessionId = null;
92	  try { sessionId = localStorage.getItem(SESSION_KEY); } catch (e) {}
93	
94	  const mic = document.getElementById("mic");
95	  const status = document.getElementById("status");
96	  const lastReply = document.getElementById("lastReply");
97	  const transcript = document.getElementById("transcript");
98	  const form = document.getElementById("textForm");
99	  const input = document.getElementById("textInput");
100	
101	  function addMessage(role, text) {
102	    const el = document.createElement("div");
103	    el.className = "msg " + role;
104	    el.textContent = text;
105	    transcript.appendChild(el);
106	    transcript.scrollTop = transcript.scrollHeight;
107	  }
108	
109	  // Once true, the traveller has granted mic access at least once: after
110	  // that, the loop stays hands-free — the agent's spoken reply
111	  // auto-resumes listening instead of waiting for another tap. A tap is
112	  // still required for the very first turn (browsers require a user
113	  // gesture to grant mic access) and the loop stops on its own once the
114	  // conversation reaches a terminal stage. This is the difference between
115	  // "a chat with voice bolted on" and something you could actually run
116	  // with the screen off.
117	  let voiceModeActive = false;
118	  const TERMINAL_STAGES = new Set(["booked", "failed"]);
119	
120	  function speak(text, stage) {
121	    if (!("speechSynthesis" in window)) return;
122	    const utter = new SpeechSynthesisUtterance(text);
123	    utter.lang = "it-IT";
124	    mic.classList.add("speaking");
125	    utter.onend = () => {
126	      mic.classList.remove("speaking");
127	      if (voiceModeActive && recognizer && !recognizing && !TERMINAL_STAGES.has(stage)) {
128	        setTimeout(() => {
129	          try { recognizer.start(); } catch (e) { /* already listening, ignore */ }
130	        }, 300);
131	      }
132	    };
133	    speechSynthesis.cancel();
134	    speechSynthesis.speak(utter);
135	  }
136	
137	  async function send(text) {
138	    if (!text || !text.trim()) return;
139	    addMessage("traveller", text);
140	    status.textContent = "…";
141	    try {
142	      const res = await fetch("/api/message", {
143	        method: "POST",
144	        headers: { "content-type": "application/json" },
145	        body: JSON.stringify({ sessionId, text }),
146	      });
147	      const data = await res.json();
148	      if (data.sessionId) {
149	        sessionId = data.sessionId;
150	        try { localStorage.setItem(SESSION_KEY, sessionId); } catch (e) {}
151	      }
152	      const stage = data.state && data.state.stage;
153	      lastReply.textContent = data.reply || "";
154	      addMessage("agent", data.reply || "");
155	      speak(data.reply || "", stage);
156	      status.textContent = TERMINAL_STAGES.has(stage)
157	        ? "Conversazione conclusa — apri una nuova pagina per ricominciare"
158	        : voiceModeActive
159	          ? "…"
160	          : "Tocca il microfono per rispondere";
161	    } catch (err) {
162	      status.textContent = "Errore di rete, riprova.";
163	    }
164	  }
165	
166	  form.addEventListener("submit", (e) => {
167	    e.preventDefault();
168	    const text = input.value;
169	    input.value = "";
170	    send(text);
171	  });
172	
173	  const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
174	  let recognizing = false;
175	  let recognizer = null;
176	
177	  if (SpeechRecognition) {
178	    recognizer = new SpeechRecognition();
179	    recognizer.lang = "it-IT";
180	    recognizer.interimResults = false;
181	    recognizer.maxAlternatives = 1;
182	
183	    recognizer.onstart = () => {
184	      recognizing = true;
185	      mic.classList.add("listening");
186	      status.textContent = "Ti ascolto…";
187	    };
188	    recognizer.onend = () => {
189	      recognizing = false;
190	      mic.classList.remove("listening");
191	    };
192	    recognizer.onerror = () => {
193	      recognizing = false;
194	      mic.classList.remove("listening");
195	      status.textContent = "Non ho sentito bene, riprova.";
196	    };
197	    recognizer.onresult = (event) => {
198	      const text = event.results[0][0].transcript;
199	      send(text);
200	    };
201	
202	    mic.addEventListener("click", () => {
203	      if (recognizing) { recognizer.stop(); return; }
204	      voiceModeActive = true;
205	      if ("speechSynthesis" in window) speechSynthesis.cancel();
206	      try { recognizer.start(); } catch (e) { /* already starting, ignore */ }
207	    });
208	  } else {
209	    status.textContent = "Riconoscimento vocale non supportato qui — usa il campo di testo.";
210	    mic.disabled = true;
211	    mic.style.opacity = "0.4";
212	  }
213	})();
214	</script>
215	</body>
216	</html>
