74	<body>
75	<main>
76	  <h1>Vela</h1>
77	  <p class="tagline">Non un sito di prenotazione: parlagli come parleresti a un umano. Padel, tennis, hotel — un'unica richiesta, in una frase.</p>
78	
79	  <div class="mic-stage">
80	    <button id="mic" aria-label="Parla con Vela">🎙️</button>
81	    <div id="status" aria-live="polite">Tocca il microfono e di' cosa vuoi</div>
82	    <div id="lastReply" aria-live="polite"></div>
83	  </div>
84	
85	  <form id="textForm">
86	    <input id="textInput" type="text" placeholder="…oppure scrivi qui se non puoi parlare ad alta voce" autocomplete="off" />
87	    <button class="send" type="submit">Invia</button>
88	  </form>
89	  <p class="hint">Il testo è un ripiego per chi non può usare la voce — l'interazione pensata è vocale, a schermo spento.</p>
90	
91	  <div id="examples">
92	    <p>Non sai da dove partire? Sono solo esempi, non l'unico modo di parlare:</p>
93	    <div class="chips">
94	      <button type="button" class="example-chip">Voglio giocare a tennis a Roma il 25 settembre, budget 500 euro, siamo in 2</button>
95	      <button type="button" class="example-chip">Non ho preferenze di città, portami dove trovi la disponibilità migliore per il padel</button>
96	      <button type="button" class="example-chip">I have three days off in June, I want to play padel somewhere warm, nothing too expensive</button>
97	    </div>
98	  </div>
99	
100	  <details>
101	    <summary>Trascrizione (per revisione)</summary>
102	    <div id="transcript" class="transcript"></div>
103	  </details>
104	</main>
105	
106	<script>
107	(function () {
108	  const SESSION_KEY = "vela.session.v1";
109	  let sessionId = null;
110	  try { sessionId = localStorage.getItem(SESSION_KEY); } catch (e) {}
111	
112	  const mic = document.getElementById("mic");
113	  const status = document.getElementById("status");
114	  const lastReply = document.getElementById("lastReply");
115	  const transcript = document.getElementById("transcript");
116	  const form = document.getElementById("textForm");
117	  const input = document.getElementById("textInput");
118	  const examples = document.getElementById("examples");
119	
120	  function addMessage(role, text) {
121	    const el = document.createElement("div");
122	    el.className = "msg " + role;
123	    el.textContent = text;
124	    transcript.appendChild(el);
125	    transcript.scrollTop = transcript.scrollHeight;
126	  }
127	
128	  // Once true, the traveller has granted mic access at least once: after
129	  // that, the loop stays hands-free — the agent's spoken reply
130	  // auto-resumes listening instead of waiting for another tap. A tap is
131	  // still required for the very first turn (browsers require a user
132	  // gesture to grant mic access) and the loop stops on its own once the
133	  // conversation reaches a terminal stage. This is the difference between
134	  // "a chat with voice bolted on" and something you could actually run
135	  // with the screen off.
136	  let voiceModeActive = false;
137	  const TERMINAL_STAGES = new Set(["booked", "failed"]);
138	
139	  function speak(text, stage) {
140	    if (!("speechSynthesis" in window)) return;
141	    const utter = new SpeechSynthesisUtterance(text);
142	    utter.lang = "it-IT";
143	    mic.classList.add("speaking");
144	    utter.onend = () => {
145	      mic.classList.remove("speaking");
146	      if (voiceModeActive && recognizer && !recognizing && !TERMINAL_STAGES.has(stage)) {
147	        setTimeout(() => {
148	          try { recognizer.start(); } catch (e) { /* already listening, ignore */ }
149	        }, 300);
150	      }
151	    };
152	    speechSynthesis.cancel();
153	    speechSynthesis.speak(utter);
154	  }
155	
156	  async function send(text) {
157	    if (!text || !text.trim()) return;
158	    if (examples) examples.hidden = true;
159	    addMessage("traveller", text);
160	    status.textContent = "…";
161	    try {
162	      const res = await fetch("/api/message", {
163	        method: "POST",
164	        headers: { "content-type": "application/json" },
165	        body: JSON.stringify({ sessionId, text }),
166	      });
167	      const data = await res.json();
168	      if (data.sessionId) {
169	        sessionId = data.sessionId;
170	        try { localStorage.setItem(SESSION_KEY, sessionId); } catch (e) {}
171	      }
172	      const stage = data.state && data.state.stage;
173	      lastReply.textContent = data.reply || "";
174	      addMessage("agent", data.reply || "");
175	      speak(data.reply || "", stage);
176	      status.textContent = TERMINAL_STAGES.has(stage)
177	        ? "Conversazione conclusa — apri una nuova pagina per ricominciare"
178	        : voiceModeActive
179	          ? "…"
180	          : "Tocca il microfono per rispondere";
181	    } catch (err) {
182	      status.textContent = "Errore di rete, riprova.";
183	    }
184	  }
185	
186	  form.addEventListener("submit", (e) => {
187	    e.preventDefault();
188	    const text = input.value;
189	    input.value = "";
190	    send(text);
191	  });
192	
193	  // Inspiration, never a menu: tapping one just sends that exact phrase as
194	  // an ordinary message — the same path as typing or speaking it — and
195	  // the chips disappear right after, same as any other first-turn UI
196	  // (they'd be clutter, and slightly misleading, once a real conversation
197	  // is under way). If a conversation is already resumed from localStorage
198	  // (sessionId present), skip showing them at all — it's not a first turn.
199	  if (examples) {
200	    if (sessionId) {
201	      examples.hidden = true;
202	    } else {
203	      examples.querySelectorAll(".example-chip").forEach((chip) => {
204	        chip.addEventListener("click", () => send(chip.textContent));
205	      });
206	    }
207	  }
208	
209	  const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
210	  let recognizing = false;
211	  let recognizer = null;
212	
213	  if (SpeechRecognition) {
214	    recognizer = new SpeechRecognition();
215	    recognizer.lang = "it-IT";
216	    recognizer.interimResults = false;
217	    recognizer.maxAlternatives = 1;
218	
219	    recognizer.onstart = () => {
220	      recognizing = true;
221	      mic.classList.add("listening");
222	      status.textContent = "Ti ascolto…";
223	    };
224	    recognizer.onend = () => {
225	      recognizing = false;
226	      mic.classList.remove("listening");
227	    };
228	    recognizer.onerror = () => {
229	      recognizing = false;
230	      mic.classList.remove("listening");
231	      status.textContent = "Non ho sentito bene, riprova.";
232	    };
233	    recognizer.onresult = (event) => {
234	      const text = event.results[0][0].transcript;
235	      send(text);
236	    };
237	
238	    mic.addEventListener("click", () => {
239	      if (recognizing) { recognizer.stop(); return; }
240	      voiceModeActive = true;
241	      if ("speechSynthesis" in window) speechSynthesis.cancel();
242	      try { recognizer.start(); } catch (e) { /* already starting, ignore */ }
243	    });
244	  } else {
245	    status.textContent = "Riconoscimento vocale non supportato qui — usa il campo di testo.";
246	    mic.disabled = true;
247	    mic.style.opacity = "0.4";
248	  }
249	})();
250	</script>
251	</body>
252	</html>
