188	  // A short filler is spoken out loud only past the LONG threshold — this
189	  // is specifically for the genuinely slow real-world steps (opening a
190	  // real cart, charging a real payment, confirming a real booking, all of
191	  // which chain several live API calls) so the traveller isn't left
192	  // wondering if anything is happening at all, without turning every
193	  // ordinary reply into unnecessary chatter.
194	  function speakFiller(text) {
195	    if (!("speechSynthesis" in window)) return;
196	    const utter = new SpeechSynthesisUtterance(text);
197	    utter.lang = "it-IT";
198	    speechSynthesis.speak(utter);
199	  }
200	
201	  // Picked from the stage the PREVIOUS turn ended on — a "yes" right after
202	  // a proposal is exactly the message that triggers the heavy real
203	  // pipeline (cart, payment, booking), so that's the one case worth a
204	  // more specific, reassuring line instead of a generic "still thinking".
205	  const FILLERS = {
206	    proposing: [
207	      "Sto verificando prezzo e disponibilità reali, un attimo…",
208	      "Ci sto mettendo un po' più del solito — sto aprendo il carrello vero e processando il pagamento, resta con me.",
209	    ],
210	    collecting_traveller: [
211	      "Sto registrando i tuoi dati…",
212	      "Il fornitore è un po' lento in questo momento, ma ci siamo quasi.",
213	    ],
214	    paying: [
215	      "Sto confermando il pagamento…",
216	      "Ci sto mettendo un po' più del solito a confermare la prenotazione, scusa l'attesa.",
217	    ],
218	    default: ["Ci penso…", "Scusa l'attesa, ci sto ancora lavorando."],
219	  };
220	  let lastStage = null;
221	  let fillerTimers = [];
222	  function clearFillers() {
223	    fillerTimers.forEach(clearTimeout);
224	    fillerTimers = [];
225	  }
226	
227	  async function send(text) {
228	    if (!text || !text.trim()) return;
229	    if (examples) examples.hidden = true;
230	    addMessage("traveller", text);
231	    mic.classList.add("thinking");
232	    status.textContent = "Ci penso…";
233	
234	    const [shortFiller, longFiller] = FILLERS[lastStage] || FILLERS.default;
235	    clearFillers();
236	    fillerTimers.push(setTimeout(() => { status.textContent = shortFiller; }, 3200));
237	    fillerTimers.push(setTimeout(() => {
238	      status.textContent = longFiller;
239	      speakFiller(longFiller);
240	    }, 7500));
241	
242	    try {
243	      const res = await fetch("/api/message", {
244	        method: "POST",
245	        headers: { "content-type": "application/json" },
246	        body: JSON.stringify({ sessionId, text }),
247	      });
248	      const data = await res.json();
249	      clearFillers();
250	      mic.classList.remove("thinking");
251	      if (data.sessionId) {
252	        sessionId = data.sessionId;
253	        try { localStorage.setItem(SESSION_KEY, sessionId); } catch (e) {}
254	      }
255	      const stage = data.state && data.state.stage;
256	      lastStage = stage;
257	      lastReply.textContent = data.reply || "";
258	      addMessage("agent", data.reply || "");
259	      speak(data.reply || "", stage);
260	      status.textContent = TERMINAL_STAGES.has(stage)
261	        ? "Conversazione conclusa — apri una nuova pagina per ricominciare"
262	        : voiceModeActive
263	          ? "…"
264	          : "Tocca il microfono per rispondere";
265	    } catch (err) {
266	      clearFillers();
267	      mic.classList.remove("thinking");
268	      status.textContent = "Errore di rete, riprova.";
269	    }
270	  }
271	
272	  form.addEventListener("submit", (e) => {
273	    e.preventDefault();
274	    const text = input.value;
275	    input.value = "";
276	    send(text);
277	  });
278	
279	  // Inspiration, never a menu: tapping one just sends that exact phrase as
280	  // an ordinary message — the same path as typing or speaking it — and
281	  // the chips disappear right after, same as any other first-turn UI
282	  // (they'd be clutter, and slightly misleading, once a real conversation
283	  // is under way). If a conversation is already resumed from localStorage
284	  // (sessionId present), skip showing them at all — it's not a first turn.
285	  if (examples) {
286	    if (sessionId) {
287	      examples.hidden = true;
288	    } else {
289	      examples.querySelectorAll(".example-chip").forEach((chip) => {
290	        chip.addEventListener("click", () => send(chip.textContent));
291	      });
292	    }
293	  }
294	
295	  const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
296	  let recognizing = false;
297	  let recognizer = null;
298	
299	  if (SpeechRecognition) {
300	    recognizer = new SpeechRecognition();
301	    recognizer.lang = "it-IT";
302	    recognizer.interimResults = false;
303	    recognizer.maxAlternatives = 1;
304	
305	    recognizer.onstart = () => {
306	      recognizing = true;
307	      mic.classList.add("listening");
308	      status.textContent = "Ti ascolto…";
309	    };
310	    recognizer.onend = () => {
311	      recognizing = false;
312	      mic.classList.remove("listening");
313	    };
314	    recognizer.onerror = () => {
315	      recognizing = false;
316	      mic.classList.remove("listening");
317	      status.textContent = "Non ho sentito bene, riprova.";
318	    };
319	    recognizer.onresult = (event) => {
320	      const text = event.results[0][0].transcript;
321	      send(text);
322	    };
323	
324	    mic.addEventListener("click", () => {
325	      if (recognizing) { recognizer.stop(); return; }
326	      voiceModeActive = true;
327	      if ("speechSynthesis" in window) speechSynthesis.cancel();
328	      try { recognizer.start(); } catch (e) { /* already starting, ignore */ }
329	    });
330	  } else {
331	    status.textContent = "Riconoscimento vocale non supportato qui — usa il campo di testo.";
332	    mic.disabled = true;
333	    mic.style.opacity = "0.4";
334	  }
335	})();
336	</script>
337	</body>
338	</html>
339

