1	export interface Env {
2	  AI: Ai;
3	  ASSETS: Fetcher;
4	  CONVERSATION: DurableObjectNamespace<import("./conversation").ConversationDO>;
5	  HOFJ_BASE_URL: string;
6	  HOFJ_BRAND: string;
7	  HOFJ_LOCALE: string;
8	  HOFJ_API_KEY: string;
9	  ANTHROPIC_API_KEY?: string;
10	  STRIPE_PUBLISHABLE_KEY?: string;
11	  /** Restricted Stripe secret key (test mode), confirmed by Vela
12	   * (2026-09-15) as the sanctioned way to create real PaymentIntents
13	   * directly against HOFJ's own Stripe account — see attemptPayment() in
14	   * conversation.ts and ARCHITECTURE.md. Server-side only, never sent to
15	   * the frontend. */
16	  STRIPE_SECRET_KEY?: string;
17	}
18	
19	/** What we've gathered from the traveller so far. Only sport/city are hard
20	 * requirements to run a search; the rest sharpen the match. */
21	export interface Slots {
22	  sport: "tennis" | "padel" | null;
23	  city: string | null;
24	  dateFrom: string | null; // YYYY-MM-DD, requested start
25	  dateTo: string | null; // YYYY-MM-DD, requested end (optional, inferred from product duration if absent)
26	  /** A date phrase heard but not yet resolved to a specific day (e.g. "nei
27	   * prossimi tre mesi") — persisted across turns so the signal survives
28	   * even when dateFrom isn't the slot being asked about *this* turn (e.g.
29	   * the traveller volunteers a vague date while city is still missing).
30	   * Checked whenever dateFrom next becomes the missing slot, not only in
31	   * the turn it was said. Cleared once a real dateFrom is resolved. */
32	  dateFromVague: string | null;
33	  /** A month the traveller hinted at ("in June", "a giugno") without a
34	   * specific day — extracted deterministically (see engine/dates.ts,
35	   * same reasoning as dateFromVague: don't trust the model with calendar
36	   * logic). Used to bias candidate selection and the date_unspecified
37	   * compromise toward that month instead of blindly offering the
38	   * earliest availability regardless of when the traveller actually
39	   * wanted to go (regression: live test offered December for a "three
40	   * days off in June" request). 1-12, or null. */
41	  preferredMonth: number | null;
42	  budget: number | null; // EUR, total for the trip
43	  /** A qualitative budget answer ("economico"/"il top"/"carino ma non
44	   * troppo caro") that doesn't map to a number — a real answer, not a
45	   * missing one, so it must not be treated as budget_unspecified. "low"
46	   * biases selection toward the cheapest relevant candidate; "mid" picks
47	   * something reasonably priced (neither cheapest nor priciest in the
48	   * pool); "high" means no ceiling, keep the default (most relevant)
49	   * selection. Mutually exclusive with `budget` in practice: interpret()
50	   * sets one or the other. */
51	  budgetTier: "low" | "mid" | "high" | null;
52	  /** Party size. Unlike city/date/budget, this is never inferred or
53	   * defaulted — the traveller must state it explicitly. See
54	   * ARCHITECTURE.md: precision policy decided 2026-09-15. */
55	  adults: number | null;
56	  preferences: string | null; // free text: "maestro", "principiante", "vista mare", ...
57	}
58	
59	export const EMPTY_SLOTS: Slots = {
60	  sport: null,
61	  city: null,
62	  dateFrom: null,
63	  dateTo: null,
64	  dateFromVague: null,
65	  preferredMonth: null,
66	  budget: null,
67	  budgetTier: null,
68	  adults: null,
69	  preferences: null,
70	};
71	
72	/** Traveller identity, collected only once we're about to open a real cart. */
73	export interface TravellerInfo {
74	  firstName: string | null;
75	  lastName: string | null;
76	  email: string | null;
77	  phone: string | null;
78	  city: string | null;
79	  postalCode: string | null;
80	  countryCode: string | null;
81	}
82	
83	export const EMPTY_TRAVELLER: TravellerInfo = {
84	  firstName: null,
85	  lastName: null,
86	  email: null,
87	  phone: null,
88	  city: null,
89	  postalCode: null,
90	  countryCode: null,
91	};
