// a proposal is exactly the message that triggers the heavy real
// pipeline (cart, payment, booking), so that's the one case worth a
// more specific, reassuring line instead of a generic "still thinking".
const FILLERS = {
  proposing: [
    "Sto verificando prezzo e disponibilità reali, un attimo…",
    "Ci sto mettendo un po' più del solito — sto aprendo il carrello vero e processando il pagamento, resta con me.",
  ],
