    "Sto registrando i tuoi dati…",
    "Il fornitore è un po' lento in questo momento, ma ci siamo quasi.",
  ],
  paying: [
    "Sto confermando il pagamento…",
    "Ci sto mettendo un po' più del solito a confermare la prenotazione, scusa l'attesa.",
  ],
  default: ["Ci penso…", "Scusa l'attesa, ci sto ancora lavorando."],
};
let lastStage = null;
let fillerTimers = [];
function clearFillers() {
  fillerTimers.forEach(clearTimeout);
  fillerTimers = [];
}

async function send(text) {
  if (!text || !text.trim()) return;
  if (examples) examples.hidden = true;
  addMessage("traveller", text);
  mic.classList.add("thinking");
  status.textContent = "Ci penso…";

  const [shortFiller, longFiller] = FILLERS[lastStage] || FILLERS.default;
  clearFillers();
  fillerTimers.push(setTimeout(() => { status.textContent = shortFiller; }, 3200));
  fillerTimers.push(setTimeout(() => {
    status.textContent = longFiller;
    speakFiller(longFiller);
  }, 7500));

  try {
    const res = await fetch("/api/message", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ sessionId, text }),
    });
    const data = await res.json();
    clearFillers();
    mic.classList.remove("thinking");
    if (data.sessionId) {
      sessionId = data.sessionId;
      try { localStorage.setItem(SESSION_KEY, sessionId); } catch (e) {}
    }
    const stage = data.state && data.state.stage;
    lastStage = stage;
    lastReply.textContent = data.reply || "";
    addMessage("agent", data.reply || "");
    speak(data.reply || "", stage);
    status.textContent = TERMINAL_STAGES.has(stage)
      ? "Conversazione conclusa — apri una nuova pagina per ricominciare"
      : voiceModeActive
        ? "…"
        : "Tocca il microfono per rispondere";
  } catch (err) {
    clearFillers();
    mic.classList.remove("thinking");
    status.textContent = "Errore di rete, riprova.";
  }
}

